(window.RAGHIB_FULL = window.RAGHIB_FULL || {})["2-1"] = [{"a": [1], "v": 1, "p": 70, "ev": 1, "ep": 75, "sid": 71, "t": "قوله - عز وجل - ﴿الٓمٓ﴾⟪2:1⟫: الآية (1) - سورة البقرة.\nاختلف الناس في الحروف التي في أوائل السور، فقالوا فيها أقوالا جلها مراد باللفظ وغير متناف على السير، لكن بعضها مفهوم بلا واسطة، وبعضخا مفهوم بواسطة، فنقول وبالله التوفيق: إن المفهوم من هذه الحروف الأظهر بلا واسطة ما ذهب إليه المحققون من أهل اللغو كالفراء وقطرب، وهو قول ابن عباس - رضي الله عنهما - وكثير من التابعين على ما بين من بعد، وهو أن هذه الحروف لما كانت هي عنصر الكلام ومادته التي تركب منها بين تعالى أن هذا الكتاب من هذه الحروف التي أصلها عندكم تنبيها لهم على إعجازهم، وأنه لو كان من عند البشر لما عجزتم مع تظاهركم عن معارضته، وأما اختصاص هذه الحروف وهذا العدد المخصوص وكونها في سور معدودة وجعل بعضها مفردا، وبعضها ثنائيا وثلاثيا ورباعيا وخماسيا، ثم لم يتجاوز ذلك واختصاصها ببعض الحروف دون بعض، ففيها عجائب وبدائع إذا اطلع عليها علم أنه كما وصفه تعالى بقوله: ﴿لَّا يَأۡتِيهِ ٱلۡبَٰطِلُ مِنۢ بَيۡنِ يَدَيۡهِ وَلَا مِنۡ خَلۡفِهِۦۖ﴾⟪41:42⟫، والقول في ذلك إن حروف التهجي قد قيل: ثمانية وعشرون.\nوقيل: تسعة وعشرون، وهذا الخلاف من حيث أن \" الألف \" حرف لا صورة له في اللفظ حتى قال بعض الناس: الألف - في حروف التهجي: حرف لا ساكن ولا متحرك، وإنما هو مدلا اعتماد له وقيل: إن الله تعالى جعل هذه الحروف طبقا للعدد الذي هو أصل العلوم، ولو توهم ارتفاعه سائر العلوم، لأن عقود الأعداد ثمانية وعشرون: آحاد: وهي تسعة, وعشرات، وهي تسعة، ومائات، وهي تسعة وألف: وهو واحد، ثم الباقي مكررات، وجعلها أيضا لمنازل القمر، وهي ثمانية وعشرون إلى غير ذلك من العجائب، وأما \" لام الألف \": فمركب من حرفين، ولا اعتداد به في حصر المفردات، وقد قال بعض النحويين: إن ذلك أن يقال: \" لا \"، ذاك أنهم لما أرادوا تعريف صورة لفظ الألف مفردة: ولم يكن سبيل إلى التفوه به مفردا، إذ لا يكون إلا مدة ضم إليها اللام ليمكن النطق به.\nوخص بذلك اللام لعله مذكورة في موضعها.\nفإذا ثبت ذلك فقد قيل: إن السور التي ذكر في أزائلها هذه الحروف تسع وعشرون، وجعل ذلك تنبيها على عدد حروف التهجي - إذا عد فيها الألف.\nوقد ذكر هذه الحروف مفردة وتنائية إلى الخمسية تنبيها أن الكتاب المنزل على رسوله مركب من كلماتهم التي هي أصولها:\n⟦1:71⟧\nإما مفردا وإما ثنائيا - إلى الخماسي - وإن أصول أبنية كلامهم لا يتجاز ذلك.\nوجاء ثلاث سور مفتتحة بمفردات، وتسع سور بالثنائيات.\nوثلاث عشرة سورة ثلاثيات، وسورتان برباعيات، وسورتان بخماسيات، وذلك \" ص \" و \" ق \" و \" ن \" و \" طه \" و \" يس \" و \" طس \" وست من الحواميم، و \" الم \" في ست سور.\nو\" الر \" في خمس سور، و \" طسم \" في سورتين، و \" المر \"، و \" المص \"، و \" كهيعص \" و \" حم عسق \"، فجعل عدد الثلاثي أكثر تنبيها أن أكثر تراكيب كلامهم الثلاثي.\nوباقيها أقل.\nوإنما جعل الثلاثي ثلاثة عشر تنبيها أن أصول الثلاثي المستعملة: ثلاثة عشر: عشرة منها للأسماء المستعملة وذلك \" فعل \" \" كعاس \"، و \" فعل \" كقفل، و \" فعل \" كقرد، وفعل كجعل، و \" فعل \" كعضد، و \" فعل \" ككتف وفعل كابل وفعل كعنق، وفعل كعنب، و (فعل) كصرد، وثلاثة للأفعل: \" فعل \" و \" فعل \" و \" فعل \" ولم يعتد ب \" فعل \": أما في الأسماء، فلأنه لم يوجد ما يعتد به، أما في الأفعل: فإن الفعل في الأصل يجب أن يبنى للفاعل ويسند إليه دون المفعول.\nوأما التسعة الثنائية، فتنبيها أن ما جاء من الكلم على حرفين تسعة اضرب ثلاثة للحروف: \" إن \" و \" من \" ومذ إذا جر به - وثلاثة للأسماء: \" من \" و \" إذ \" وهذا إذا رفع به.\nوثلاثة للأفعال في الاسعمال، نحو \" قل \"، و \" بع \" و \" خف \" وأما الثلاثة المفردة: فتنبيها أن الحروف ثلاثة أضرب مفتوح ومكسور وساكن، نحو: له، وبه، ولام التعريف، وأما الرباعيان والخماسيان، فتنبيها أن لكل واحد منهما ساكن أصلا وملحقا به، أما الأصل: فكجعفر وسفرجل، وأما الملحق بهما: فكقرد وحجنكل ، واقتصر من حروف التهجي على النصف منها - وهو أربعة عشر حرفا من غير تكرير - لتدل على حكم عجيبة.\nولما خص نصفها بالذكر أورد فيها من الحروف المجهورة والمهموسة والشديدة، وما ليس بشديدة، واللينة والمطبقة وحروف البدل وما لا يصح فيه الإدغام، وما لا يدغم فيما قاربه، ولا يدغم ما قاربه فيه، وما لا يدغم فيما قاربه، ويدغم ما قاربه فيه، ومن حروف اللقلقة ومن الحروف التي للعرب دون العجم، من كل ذلك ما هو زوج، واحتمل التنصيف فإنه أخرج نصفه، ومن كل ما هو فرد لا يحتمل التنصيف نصفه بإسقاط حرف أو زيادة حرف، وأما الحروف الذلقية والحلقية، والزوائد، فقد زيد فيها على النصف بخاصية فيها: من ذلك: الحروف المجهورة: وهي ما أشبع للاعتماد على منبعه،\n⟦1:72⟧\nولم يجر معه النفس، وهي تسعة عشر حرفا يجمعها: (زاد ظبي غنج لي ضمورا إذ قطع) أسقط منها الألف الزائدة التي قيل فيها: إنه لم يعتد بها من حيث لا تكون إلا مدة، وذكر نصفها في هذه الأربعة عشر، وهي تسعة يجمعها: \" لن يقطع أمر \".\nوالمهموسة: وهي: ما ضعف الاعتماد على منبعه، وذلك عشرة يجمعها: \" (ستشحثك خصفه) ذكر منها في هذه الأربعة عشر نصفها، وهي ما يجمعها: (صه حسك) والشديدة: وهي ثمانية يجمعها: \" أجدت طبقك \" ذكر نصفها، ويجمعها \" أقطك \" وباقيها [رخوة] وهو: أحد وعشرون، إذا سقط منها الألف فنصفها عشرة يجمعك \" حمس على نصره \".\nواللينة حرفان - سوى الألف: الواو والياء، وفي هذه الأربعة عشر أحدهما: وهو الياء، والمطبقة أربعة: ص، ض، ط، ظ.\nذكر اثنان منها، وهي: الصاد والطاء.\nوحروف البدل اثنا عشر حرفا - فيما ذكر سيبويه - يجمعها: (أجد طويت منها): ذكر منها ستة يجمعها \" أهطمين \" وترك باقيها.\nوإنما لم يجر مجرى غيرها في أن ترك منها الألف ثم نصف، بل زيد لأمر اختص به باب البدل، وهو أن الألف في باب البدل أكثر من سائر الحروف، فلم يجز الإخلال بها في باب الإبدال وأما على غير طريقة سيبويه، فقد بلغ حروف البدل ثمانية عشر، فعد فيها اللام بدلا من النون في \" أصيلان \" والصاد تبدل من \" السين \" في \" الصراط \" و \" الثاء \" من \" الفاء \" في \" فروع الدلو \" والفاء من التاء في \" جدث \" و \" جدف \" و \" ثوم \" و \" فوم \" والعين من الهمزة في عنعنة تميم، نحو قوله:\nأأن ترسمت من خرقاء منزلة.\nفي \" أأن ترسمت \" والباء من الميم \" باسمك \" في \" ما اسمك \" والزاي من السين في قولهم: \" زقر \" أي \" سقر \" - فعلى هذا - في الحروف من الثمانية عشر تسعة، وهي الستة المذكورة واللام، والصاد، والعين.\nوما لا يصح فيه الإغام: اثنان: الهمزة والألف.\nوذكر أحدهما.\nوما لا يدغم ولا يدغم فيه: فالواو والياء - إذا انفتح ما قبلهما - وقد ذكر أحدهما.\nوأما الحروف التي لا يدغم فيما قاربها، ويدغم ما قاربها فيها: فهي الميم، والراء، والشين، والفاء، وقد ذكر من هذه الحروف اثنان، وأما حروف اللقلقة: فخمسة: القاف، والجيم، والطاء، والدال، والباء، وذكر منها اثنان: الطاء والقاف وهما\n⟦1:73⟧\nأقوى الخمسة.\nوأما الحروف التي للعرب دون العجم: فالضاد والحاء، وقد ذكر أحدهما.\nوأما الحروف الذلقية: وهي التي ذلقت وسهلت على اللسان، فستة يجمعها \" رمل فنب \".\nوحروف الحلق وهي ستة: الحاء، والخاء، والعين، والغين، والهاء، والهمزة، فقد ذكر من النوعين أكثر من النصف للتنبيه على كثرة وقوعهما في الكلام، إذ قل ما ينفك رباعي وخماسي من حرف أو حرفين وثلاثة من هذه الحروف، فلما كثر وقوعها في الكلام أيد المذكور منهما على النصف تنبيها على ذلك.\nوأما الزوائد: فعشرة يجمعها (اليوم تنساه) وقع في هذه الحروف منها سبعة لخاصية فيها، وهي التنبيه على أن البناء من الكلمة قد يبلغ سبعة أحرف بالزيادة، فهذه هي التي زاد المذكور منها على النصف لفائدة تختصه وحكمة تقتضيه.\nوما روي عن ابن عباس - رضي الله تعالى عنهما - أن هذه الحروف اختصار من كلمات، فمعنى \" الم \": أنا الله أعلم، ومعنى \" المر \" أنا الله أعلم وأرى، فإشارة منه إلى ما تقدم.\nوبيان ذلك ما ذكره بعض المفسرين أن قصده بهذا التفسير ليس أن هذه الحروف مختصة بهذه المعاني دون غيرها، وإنما أشار بذلك إلى ما فيه الألف واللام والميم من الكلمات تنبيها أن هذه الحروف منبع هذه الأسماء، ولو قال: إن اللام يدل على \" اللعن \"، والميم على \" المكر \" لكان يحمل، ولكن تحرى في المثال اللفظ الأحسن، كأنه قال: هذه الحروف هي أجزاء ذلك الكتاب.\nومثل هذا في ذكر نبذ تنبيها على نوعه قول ابن عباس - رضي الله عنهما في قوله تعالى: ﴿ثُمَّ لَتُسۡـَٔلُنَّ يَوۡمَئِذٍ عَنِ ٱلنَّعِيمِ﴾⟪102:8⟫ أنه الماء الحار في الشتاء، ولم يرد به أن النعيم ليس إلا هذا، بل أشار إلى بعض ما هو نعيم تنبيها على سائره، فكذلك أشار بهذه الحروف على ما يكتب منها، وعلى ذلك ما رواه السدي عنه أن ذلك حروف إذا ركبت يحصل منها اسم الله.\nوكذا ما روي عنه أنه قال: هي أقسام غير مخالف لهذا القول، وذلك أن الأقسام الواردة في فواتح السور إنما هي بقسم وأجوبتها تنبيه عليها.\nفيكون قوله: \" ألم ذلك الكتاب جملة في تقدير مقسم بها.\nوقوله: \" لا ريب فيه \" جوابها، ويكن إقسامه بها تنبيها على عظم موقعها، وعلى عجزنا عن معارضة كتابه المؤلف منها.\nفإن قيل: لو كان قسما لكان فيه حرف القسم.\nقيل: إن حرف القسم يحتاج إليه إذا كان المقسم به مجرورا.\nفأما إذا\n⟦1:74⟧\nكان مرفوعا نحو و \" أيم الله، أو منصوبا، نحو يمين الله فليس بمحتاج إلى ذلك وما قاله زيد بن أسلم والحسن، ومجاهد، وابن جريج أنها أسماء للسور فليس بمناف للأول، فكل سورة سميت بلفظ متلو منها، فله (معنى) في السورة معلوم.\nوعلى هذا القصائد والخطب المسماة بلفظ منه يفيد معنى فيها، وكذلك ما قاله أبو عبيدة، وروي أيضا عن مجاهد، وحكاه قطرب والأخفش.\nأن هذه الفواتح دلائل على انتهاء السورة التي قبلها، وافتتاح ما بعدها، فإن ذلك يقتضي من حيث إنها لم تقع إلا في أوائل السور ولا يقتضي أن لا معنى لها سواه، كما أن بسم الله في أوائل السور يقتضي ما قالوه ولا يوجب ذلك أن لا معنى سواه.\nوما ذكر من أن هذه الحروف قصد بها الرد على من قال: إن النبي - صلى الله عليه وسلم - كان يتلقن ما يودعه القرآن من بعض الأعجمين، وذلك في قوله: ﴿وَلَقَدۡ نَعۡلَمُ أَنَّهُمۡ يَقُولُونَ إِنَّمَا يُعَلِّمُهُۥ بَشَرٞۗ لِّسَانُ ٱلَّذِي يُلۡحِدُونَ إِلَيۡهِ أَعۡجَمِيّٞ وَهَٰذَا لِسَانٌ عَرَبِيّٞ مُّبِينٌ﴾⟪16:103⟫ فذلك شبيه أن هذه الصورة المخصوص بها القرآن، هي من النظم الذس أصوله عندكم، وذاك أن القوم لم يدعوا أن لفظ هذا القرآن أعجمي، وإنما ادعوا أن معناه مأخوذ عنهم ولهذا قال تعالى: ﴿فَأۡتُواْ بِعَشۡرِ سُوَرٖ مِّثۡلِهِۦ مُفۡتَرَيَٰتٖ﴾⟪11:13⟫ فإذا: المعنى يرجع إلى ما تقدم بأنه تنبيه على إعجازه.\nوما قاله قطرب إنه قصد بها صرف أسماع المشركين إلى الاستماع إليه لما تواصلوا بأن لا يستعموا له حتى قال تعالى: ﴿وَقَالَ ٱلَّذِينَ كَفَرُواْ لَا تَسۡمَعُواْ لِهَٰذَا ٱلۡقُرۡءَانِ وَٱلۡغَوۡاْ فِيهِ لَعَلَّكُمۡ تَغۡلِبُونَ﴾⟪41:26⟫ فإنما يشير به أيضا إلى المعنى المتقدم، لأنه تعالى قصج بصرف أسماعهم تنبيههم على عجزهم عن معارضته، وأن من حقكم إذا عجزتم عن مثله أن تتدبروا آياته، وأن تعرفوا أنه حق فلا تلغوا فيه.\nوما روي عن اين عباس - رضي الله عنهما - أنه قال: الألف من \" الم \" على \" الله \"، اللام على \" جبرائيل \"، والميم على \" محمد \"، فدل بذلك على أن القرآن (من الله) - عز وجل - مبدؤه، وأن الواسطة: \" جبريل \".\nومنتهاه إلى محمد.\nفهذا صحيح ودال على ما تقدم، وفيه نبه بمخرج \" الألف \" الذي هو مبدأ مخارج الحروف على المبدأ، وهو الله تعالى، وبمخرج اللم الذي هو أوسط المخارج على جبريل، وبمخرج الميم الذي هو منتهى المخارج على المنتهى الذي هو النبي - عليه السلام -.\n⟦1:75⟧\nفكأنه قال: من هذه الحروف الدالة على الأسباب الثلاثة حصول الكتاب الذي عجزتم عن الإتيان بمثله.\nوما قاله الربيع بن أنس أن هذه الحروف حروف الجمل، وأن ذلك من علوم خاصتهم، وقد نبه بها على مدد، فذلك غير ممتنع أن يكون مع المعنى الأول مرادا، بدلالة أن النبي - عليه السلام - لما أتاه اليهود فسألوه عما أنزل عليه، تلا عليهم \" الم \"، فحسبوه، وقالوا: إن ملكا يبقى إحدى وسبعين سنة لقصير المدة فعل غيره؟ فقال: \" آلر \"، و \" آلمر \" و \" آلمص \" فقالوا: خلطت علينا، فإنا لا ندري بأيها نأخذ.\nفتلاوة النبي - عليه السلام - ذلك عليهم، وتقريرهم على استنباطهم دلالة أنه لا يمتنع أن يكون في كل واحدة دلالة على مدة لأمر ما.\nوأما ما حكي عنالزبيري أن هذه الحروف ذكرت علما منه تعالى أن يكون في هذه الامة من يزعم أن القرآن ليس بكلام الله، وإنما هو حكاية كلامه، فأراد أن يبين أن القرآن مما يكتب ويخبر عن أبعاضه وأجزائه بالحروف التي هي معلومة إنها محدثة، فإن هذا القول من الوهي بحيث يستغنى عن إظهار بطلانه، إذ لا يقول أحد إن الكتاب بما هو كتاب ليس بمؤلف من هذه الحروف وإن كانوا قد اختلفوا في القرآن.\nبل هو مقصور على الكتاب، أو المراد به هو غيره."}, {"a": [2], "v": 1, "p": 75, "ev": 1, "ep": 78, "sid": 76, "t": "قوله تعالى: ﴿ذَٰلِكَ ٱلۡكِتَٰبُ﴾⟪2:2⟫ الآية (2) - سورة البقرة.\nقال أبو عبيدة: عنى به هذا الكتاب.\nوقال غيره: عنى هو الكتاب، فظن بعض من لم يتقو في الحقائق أن قولهم: \" ذلك \" قد يجئ بمعنى \" هذا \" و \" هو \" ليس الأمر على ما ظنوه.\nوإنما قصد هذا المفسر أن يبين أن الاسم الذي فيه الألف واللام هو الخبر، لا لأنه وصف والخبر منتظر، كقوله تعالى: ﴿إِن كَانَ هَٰذَا هُوَ ٱلۡحَقَّ﴾⟪8:32⟫ والفصل كما يقع بالمضمرات فإنه يقع بالمبهمات\nفإن قيل: إذا كان هذا المعنى ما قدمت في \" الم ذلك الكتاب \" فهلا قيل: \" ذلك الكتاب ألم \" فإنه قد علم أن حروف التهجي - كما يكون الكتاب المشار إليه - قد يكون شعرا وخطبة ورسالة.\nوقد تقرر أن العام إذا أخبر عنه بالخاص كان كذبا، نحو قولهم: الحيوان إنسان وإذا أخبر عن الخاص بالعام كان صدقا، نحو قولهم: الإنسان حيوان، فيحصل من ذلك أنه إذا قيل: \" الم\n⟦1:76⟧\nذلك الكتاب - كان كذبا على هذا - وإذا قيل: \" ذلك الكتاب الم \" كان صدقا؟ قيل: في ذلك الكتاب جوابان أحدهما: أن يجعل \" ذلك الكتاب \": مبتدأ.\nو\" الم \": خبرا له مقدما ، وتقديمه على كون العناية به أصدق كما تقدم.\nوالثاني: أنه قد يقال: الإنسان زيد.\nبمعنى غير معنى \" زيد إنسان \" وهو أن يراد أن كما الإنسانية موجود في زيد.\nفكأنه قيل: كمال حروف التهجي موجود في هذا الكتاب والمكتوب في التعارف اسم للمكتوب، أي: المنظوم كتابة، وقد يعبر عن المنظوم عبارة قبل أن يكتب بالكتاب.\nقوله تعالى: ﴿لَا رَيۡبَۛ فِيهِۛ﴾⟪2:2⟫ الآية: (2) - سورة البقرة.\nقال المفسرون: معناه لا شك فيه،\nفإن قيل: كيف نفى الريب عنه، وقد علم تشكك كثير من الناس فيه؟ قيل: في ذلك أجوبة: الأول: إن ذلك نفي على معنى النهي نحو قوله: ﴿فَلَا رَفَثَ وَلَا فُسُوقَ وَلَا جِدَالَ فِي ٱلۡحَجِّۗ﴾⟪2:197⟫، بدلالة قوله: ﴿فَلَا تَكُونَنَّ مِنَ ٱلۡمُمۡتَرِينَ﴾ وقوله: ﴿فَلَا يَكُن فِي صَدۡرِكَ حَرَجٞ مِّنۡهُ﴾⟪7:2⟫\nفإن قيل: الشك لا يقصده الإنسان، فكيف ينهى عنه؟ قيل: اللفظ لذلك، والمعنى حث على التدبر والتفكر النافيين للشك.\nوالثاني: أنه يقال: رابني كذا، إذا تحققت منه الريبة، وأرابني: أوهمني الريبة.\nقال الشاعر:\nأخوك الذي إن ربته قال إنما. . . أربت وإن عاتبته لان جانبه\nفالقرآن لا ريب فيه، وإن كان فيه ارتياب من بعض الكفار، والثالث أنه يقال: هذا لا ريب فيه، والقصد إلى أنه حق، تنبيها أن الريب يرتفع عن عند التدبير والتأمل، والرابع: أنه لا ريب في كونه مؤلفا من حروف التهجي وقد عجزتم عن معارضته، والخامس لا ريب فيه للمتقين، ويكون خبر ﴿لَا رَيۡبَۛ فِيهِۛ﴾⟪2:2⟫ قوله تعالى: (للمتقين) وهدى نصب على الحال أو خبر ابتداء مضمر في موضع الحال.\nقوله عز وجل -: ﴿هُدٗى لِّلۡمُتَّقِينَ﴾⟪2:2⟫ الآية: (2) - سورة البقرة.\nقد تقدم الكلام في الهداية.\nأما اختصاص المتقين، فلأن الهداية: نصب العلم ليهتدي به الناس فله موضوع هو المبدأ: وذلك نصب العلم للكافة.\nوغاية: وهو الاهتداء به، فيقال: ﴿هُدٗى لِّلۡمُتَّقِينَ﴾⟪2:2⟫ لما لم يهتد به غيرهم.\nومثاله: من بنى مسجدا مباحا للكافة.\nيصح أن يقول: \" بنيت هذا المسجد للناس كافة \"، اعتبارا بالمبدأ.\nويصح أن يقول: بنيته للمصلين فيه، اعتبارا بالغاية.\nوطريقة أخرى: وهي أن\n⟦1:77⟧\n\" اللام \" في قوله القائل \" خرجت لأظفر \" يقال على وجهين: أحدهما أن المقصود بالخروج: الظفر والثاني: أن الحاصل منه الظفر، لا أنه قصد به، وعلى ذلك قوله تعالى: ﴿فَٱلۡتَقَطَهُۥٓ ءَالُ فِرۡعَوۡنَ لِيَكُونَ لَهُمۡ عَدُوّٗا وَحَزَنًاۗ﴾⟪28:8⟫ فقوله: هدى للمتقين: تنبيه على حصول الهدى لهم، وإن كان القصد لهم ولغيرهم.\nوطرقة ثالثة - إذا تؤملت تصور عنها جواب مسائل كثيرة في القرآن - وهو أن الله تعالى جعل لنا طبين طبا بدنيا، وطبا دينيا.\nوكل واحد منهما ضربان: أحدهما: إعادة الصحة.\nوالآخر: حفظ الصحة.\nقد أجرى العادة أن الذي يحفظ به الصحة غير الذي يعاد به الصحة أما في الطب البدني: فالذي يعاد به الصحة العقاقير والأدوية.\nوالذي يحفظ به الصحة فالغذاء والأطعمة، وأما في الطب الديني فالذي يعاد به الصحة صقل العقل واستعماله في تدبر الدلالات، وتعرف المعجزات، ومعرفة النبوات.\nوالذي يحفظ به الصحة: تدبر الكتاب المنزل، وتتبع سنن النبي المرسل.\nفكما أن من لم يستفد الصحة في الطب البدني، إذا تغذى، كان ذلك ضررا عليه، ومتى أعاد صحته كان تناول الغداء عائدا بنفع إليه، كذا من لم يستفد صحة عقله بتدبر الدلالات كان القرآن ضررا عليه، ومتى استعمل ذلك وتهذب فيه، جلب بالاستماع إلى القرآن نفعا إليه.\nوعلى ذلك قوله تعالى: ﴿وَنُنَزِّلُ مِنَ ٱلۡقُرۡءَانِ مَا هُوَ شِفَآءٞ وَرَحۡمَةٞ لِّلۡمُؤۡمِنِينَ وَلَا يَزِيدُ ٱلظَّٰلِمِينَ إِلَّا خَسَارٗا﴾⟪17:82⟫ وقوله: ﴿وَإِذَا مَآ أُنزِلَتۡ سُورَةٞ فَمِنۡهُم مَّن يَقُولُ أَيُّكُمۡ زَادَتۡهُ هَٰذِهِۦٓ إِيمَٰنٗاۚ﴾⟪9:124⟫ إلى قوله: ﴿فَزَادَتۡهُمۡ رِجۡسًا إِلَىٰ رِجۡسِهِمۡ وَمَاتُواْ وَهُمۡ كَٰفِرُونَ﴾⟪9:125⟫ وأما [التقوى] فهو: جعل النفس في وقاية مما يخاف.\nهذا حقيقته.\nثم يسمى تارة \" الخوف \" التقوى.\nوالتقى: خوفا على تسمية المقتضي باسم المقتضي والمقتضي باسم المقتضي وفي التعارف: حفظ النفس عن كل ما يؤثم.\nولها منازل: الأول: ترك المحظور.\nوذلك لا يتم إلا بترك بعض المباح مما يليه.\nولذلك قال عليه السلام \" من يرتع حول الحمى يوشك أن يقع فيه \" وقيل: من\n⟦1:78⟧\nلم يجعل بينه وبين محارم الله سترا من حلال، فحقيق به أن يقع فيها.\nفقوله تعالى: ﴿إِنَّمَا يَتَقَبَّلُ ٱللَّهُ مِنَ ٱلۡمُتَّقِينَ﴾⟪5:27⟫ أي: التاركين للمحظورات.\nوقال ﴿فَمَنِ ٱتَّقَىٰ وَأَصۡلَحَ فَلَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ﴾⟪7:35⟫ وقال: ﴿إِنَّ ٱللَّهَ مَعَ ٱلَّذِينَ ٱتَّقَواْ وَّٱلَّذِينَ هُم مُّحۡسِنُونَ﴾⟪16:128⟫ فجعل \" المتقي \" - في الآيتين - غير المصلح والمحسن.\nوالثاني: من منازل التقوى - أن يتعاطى الخير من تجنب الشر، وإياه عنى الله تعالى بقوله: ﴿وَسِيقَ ٱلَّذِينَ ٱتَّقَوۡاْ رَبَّهُمۡ إِلَى ٱلۡجَنَّةِ زُمَرًاۖ﴾⟪39:73⟫ والثالث منها: التبرؤ من كل شيء سوى الله - عز وجل - فلا سكون إلى النفس ولا إلى شيء من القنيات والجاه والأعراض.\nوهو المعنى بقوله تعالى: ﴿ٱتَّقُواْ ٱللَّهَ حَقَّ تُقَاتِهِۦ﴾⟪3:102⟫ وما وعدناه بقوله تعالى: ﴿وَٱلَّذِينَ ٱهۡتَدَوۡاْ زَادَهُمۡ هُدٗى وَءَاتَىٰهُمۡ تَقۡوَىٰهُمۡ﴾⟪47:17⟫ ورجاناه بقوله: ﴿وَأَنذِرۡ بِهِ ٱلَّذِينَ يَخَافُونَ أَن يُحۡشَرُوٓاْ إِلَىٰ رَبِّهِمۡ﴾⟪6:51⟫ إلى قوله: ﴿لَعَلَّهُمۡ يَتَّقُونَ﴾ فهذه المنازل مرتب بعضها على بعض.\nوقد فسر قوله تعالى: ﴿هُدٗى لِّلۡمُتَّقِينَ﴾⟪2:2⟫ على الوجوه الثلاثة، فقيل: عني به التاركين لمحارم الله.\nوقال ابن عباس - رضي الله عنهما: عني به الخائفين عقوبته الراجين رحمته، وقال بعض المتقدمين: معنى ﴿هُدٗى لِّلۡمُتَّقِينَ﴾⟪2:2⟫ أي وصلة للمنقطعين إليه عن الأغيار الذين نزع عن قلوبهم حب الشهوات.\nفهذا نظر منهم إلى الغاية."}, {"a": [3], "v": 1, "p": 79, "ev": 1, "ep": 83, "sid": 80, "t": "قوله - عز وجل: ﴿ٱلَّذِينَ يُؤۡمِنُونَ بِٱلۡغَيۡبِ﴾⟪2:3⟫ الآية: (3) سورة البقرة.\nالإيمان: التصديق بالشيء، ولا يكون التصديق إلا عن علم.\nولذلك قال تعالى: ﴿إِلَّا مَن شَهِدَ بِٱلۡحَقِّ وَهُمۡ يَعۡلَمُونَ﴾⟪43:86⟫ فالإيمان: اسم لثلاثة أشياء: علم بالشيء وإقرار به، وعمل بمقتضاه، إن كان لذلك المعلوم عمل، كالصلاة والزكاة.\nوهذا هو الأضل، ثم قد يستعمل في كل واحد من هذه الثلاثة، فقال: \" فلان مؤمن \"، ويعني به أنه مقر بما يحصن دمه وماله وإياه عن النبي - صلى الله عليه وسلم - بقوله: \" أمرت أن أقاتل الناس حتى يقولوا لا إله إلا الله فإذا قالوها عصموا مني دماءهم وأموالهم إلا بحقها \"، وبذلك حكم - عليه السلام - على الجارية التي عرضت عليه فسألها ما سألها.\nثم قال: \" اعتقها فإنها مؤمنة \" ويقال: \" مؤمن \" ويراده: أنه يعرف الأدلة الإقناعية التي يحصل معها سكون النفس، وإياه عنى النبي - صلى الله عليه وسلم - بقوله: \" من قال لا إله إلا الله مخلصا دخل الجنة \"، ويقال: \" مؤمن \"، ويعني به: أنه يسكن قلبه إلى الله من غير تلفت إلى شيء من عوارض الدنيا وإياه عنى الله تعالى بقوله: ﴿إِنَّمَا ٱلۡمُؤۡمِنُونَ ٱلَّذِينَ إِذَا ذُكِرَ ٱللَّهُ وَجِلَتۡ قُلُوبُهُمۡ﴾⟪8:2⟫ الآية، وبقوله: ﴿أُوْلَٰٓئِكَ كَتَبَ فِي قُلُوبِهِمُ ٱلۡإِيمَٰنَ﴾⟪58:22⟫ و \" الغيب \": ما لا يقع تحت الحواس، ولا تقتضيه بداية العقول، وإنما يعلم إما بواسطة علم ما أو الاستشهاد به عليه، وإما بخبر الصادق، وهو الذي دفعه قوم، فلزمهم اسم الإلحاد، لأن الإلحاد: دفع أخبار الغيب، وقول: \" زر بأن \": الغيب: هو القرآن.\nوقول عطاء: إنه القدر: تمثيل لبعض ما هو غيب.\nوليس ذلك بخلاف بينهم، بل كل أشار إلى الغيب بمثال وكذا ما روى أبو جمعة \" إنا كنا مع رسول الله - صلى الله عليه وسلم - فقلنا يا رسول الله: هل قوم أعظم أجرا منا، آمنا بك واتبعناك.\nقال: ما يمنعكم من ذلك ورسول الله بين أظهركم يأتيكم بالوحي من السماء، بل قوم من بعدكم يأتيهم كتاب بين لوحين،\n⟦1:80⟧\nفيؤمنون به، ويعملون بما فيه، أولئك أعظم أجرا منكم \" فتبين منه - عليه السلام - أن من بعده يحتاج إلى نظر أكثر من نظر الذين شاهدوه فقد كفوا كثيرا من أخبار الغيب.\nوقوله: \" بالغيب \" في موضع المفعول.\nكقوله: ﴿وَبِٱلۡأٓخِرَةِ هُمۡ يُوقِنُونَ﴾⟪2:4⟫ وقال بعضهم: معناه: يؤمنون إذا غابوا عنكم، ولم يكونوا كالمنافقين الذين ﴿وَإِذَا خَلَوۡاْ إِلَىٰ شَيَٰطِينِهِمۡ قَالُوٓاْ إِنَّا مَعَكُمۡ إِنَّمَا نَحۡنُ مُسۡتَهۡزِءُونَ﴾⟪2:14⟫.\nوقوى ما قاله بقوله تعالى: ﴿ٱلَّذِينَ يَخۡشَوۡنَ رَبَّهُم بِٱلۡغَيۡبِ﴾ وقوله ﴿وَخَشِيَ ٱلرَّحۡمَٰنَ بِٱلۡغَيۡبِۖ﴾⟪36:11⟫، قول الشاعر:\nوهم بغيب وفي عمياء ما شعروا\nويكون \" بالغيب \" على هذا في موضع الحال.\nومفعول: \" يؤمنون \": محذوف.\nوقال بعض المتأخرين من المتكلمين: يحمل قوله تعالى \" بالغيب \" على المعنيين وخفي عليه أن ذلك لا يصح، فإن وبالغيب في القول الأول: مفعول: في القول الثاني: حال لا يصح أن يقال ضربت راكبا، و \" راكب \" يكون مفعولا: ل \" لضربت \" و \" حالا \" للفاعل.\nوالوجه: هو القول الأول، لأنه مستوعب لمعنى الثاني وزائد عليه، إذ كل من آمن - على الوجه الأول - فلا شك أنه بخلاف من يقول: ﴿إِنَّمَا نَحۡنُ مُسۡتَهۡزِءُونَ﴾⟪2:14⟫ وقيل: معنى قوله: ﴿يُؤۡمِنُونَ بِٱلۡغَيۡبِ﴾⟪2:3⟫ يعني بالقلب، والنور الذي آتاهم الله وهو العقل، ومعناه: آمنوا بقلوبهم، بخلاف من أخبر الله تعالى عنهم بقوله: ﴿وَمِنَ ٱلنَّاسِ مَن يَقُولُ ءَامَنَّا بِٱللَّهِ وَبِٱلۡيَوۡمِ ٱلۡأٓخِرِ وَمَا هُم بِمُؤۡمِنِينَ﴾⟪2:8⟫ ومن حكى عنهم: ﴿يَقُولُونَ بِأَفۡوَٰهِهِم مَّا لَيۡسَ فِي قُلُوبِهِمۡۚ﴾⟪3:167⟫ وهذا أيضا يرجع إلى الأول عند التحقيق، وقيل: \" يؤمنون \" من: \" آمن فلان \" - أي: صار ذا أمن نحو أحال وأجرب.\nومعناه: صاروا ذوي أمن بظهر الغيب بأن ما أخبروا به حق، فتطمئن قلوبهم بذكر الله.\n⟦1:81⟧\nقوله (عز وجل): ﴿وَيُقِيمُونَ ٱلصَّلَوٰةَ﴾⟪2:3⟫:\nإقامة الصلاة: توفية حدودها وإدامتها، وتخصيص \" الإقامة \" تنبيه على أنه لم يرد إيقاعها فقط.\nولهذا لم يأمر بالصلاة ولم يمدح بها إلا بلفظ الإقامة نحو: ﴿وَأَقَامَ ٱلصَّلَوٰةَ﴾ وقوله: ﴿وَٱلۡمُقِيمِينَ ٱلصَّلَوٰةَۚ﴾⟪4:162⟫ و ﴿ٱلَّذِينَ يُقِيمُونَ ٱلصَّلَوٰةَ﴾ ولم يقل المصلي إلا في المنافقين ﴿فَوَيۡلٞ لِّلۡمُصَلِّينَ ۝ ٱلَّذِينَ هُمۡ عَن صَلَاتِهِمۡ سَاهُونَ﴾⟪107:4-5⟫ وذلك تنبيه أن المصلين كثير والمقيمين لها قليل، كما قال عمر - رضي الله عنه [الحاج قليل والركب كثير]، ولهذا قال عليه السلام:\n\" من صلى ركعتين مقبلا بقلبه على الله خرج من ذنوبه كيوم ولدته أمه \" فذكر مع قوله - صلى الله عليه وسلم - الإقبال بقلبه على الله تنبيها على معنى الإقامة، وبذلك عظم ثوابه وكثير من الأفعال التي حث تعالى على توفية حقه ذكره بلفظ الإقامة نحو: ﴿وَلَوۡ أَنَّهُمۡ أَقَامُواْ ٱلتَّوۡرَىٰةَ وَٱلۡإِنجِيلَ﴾⟪5:66⟫ ونحو: ﴿وَأَقِيمُواْ ٱلۡوَزۡنَ بِٱلۡقِسۡطِ﴾⟪55:9⟫ تنبيها على المحافظة على تعديله.\nوقال أبو علي الجبائي: الصلاة لما جاورها القيام صح أن يعبر عن المصلى بالقيام وهذا بعيد، لأن المجاور للصلاة القيام لا الإقامة، ثم مع القول المتقدم لا يعرج على هذا، وقوله - عز وجل - ﴿وَمِمَّا رَزَقۡنَٰهُمۡ يُنفِقُونَ﴾⟪2:3⟫ الرزق: لفظ مشترك، يقال للعطاء الجاري تارة، وللنصيب تارة، ولما يصل إلى الجوف ويتغذى به تارة.\nفقوله تعالى: ﴿وَتَجۡعَلُونَ رِزۡقَكُمۡ أَنَّكُمۡ تُكَذِّبُونَ﴾⟪56:82⟫ يعني نصيبكم من النعمة.\nوقوله: ﴿وَفِي ٱلسَّمَآءِ رِزۡقُكُمۡ﴾⟪51:22⟫ تنبيه على ان الحظوظ بالمقادير.\nوقوله: ﴿وَأَنفِقُواْ مِن مَّا رَزَقۡنَٰكُم﴾⟪63:10⟫ ﴿وَمِمَّا رَزَقۡنَٰهُمۡ﴾⟪2:3⟫ محمول على المباح دون الحظور لأمرين: أحدهما : [أنه] حث\n⟦1:82⟧\nوعلى الإنفاق، ومدح لفاعل، ولا يحث ولا يمدح بانفاق المحظورات.\nوالثاني: باضافته إليه وتمكينه منه، حيث قال: ﴿وَمِمَّا رَزَقۡنَٰهُمۡ﴾⟪2:3⟫ من شرط ما يضاف إليه من الأفعال مفصلا أن يخص الأفضل، فالأفضل، وإن كان قد يضاف إليه الأفعال كلها على سبيل العموم بمعنى: أنه هو السبب الذي لولاه - تعالى - لم يحصل ولم يكن بوجه والظاهر - من إنفاق ما رزقه الله - المال، وذلك عام فيما يخرج من الزكاة المفروضة، ومن العطايا النافلة، بدلالة أن ذلك مدح منه.\nوالمدح قد يستحق بالفرض والنفل، وما روي عن ابن عباس - رضي الله عنهما - أنه عنى \" الصلوات المفروضة \" والزكوات [المحدودة] فإنه، ذكر أوكد ما يستحق به المدح، إذ لا يعتد بالنفل ما لم يؤت بالفرض، لقوله عليه السلام: \" إن الله لا يقبل نافلة حتى تؤدى الفريضة \" وروي عن ابن مسعود - رضي الله عنه - \" إن المؤمن ليؤجر في كل شيء حتى اللقمة يضعها في في امرأته \" فالإنفاق من الرزق بالنظر العامي من المال كما تقدم.\nوأما بالنظر الخاصي:\nفقد يكون الإنفاق من جميع المعاون التي أتانا الله - عز وجل - من النعم الباطنة والظاهرة، كالعلم والقوة والجاه والمال.\nألا ترى إلى قوله - عليه السلام - \" إن علما لا يقال به ككنز لا ينفق منه \" وبهذا النظر عد الشجاعة وبذل الجاه وبذل العلم من الجود حتى قال الشاعر:\nوالجود بالنفس أقصى غاية الجود.\nوقال آخر:\nبحر يجود بماله وبجاهه. . . والجود كل الجود بذل الجاه\nوقال حكيم: الجود التام: بذل العلم.\nفمتاع الدنيا عرض زائل ينقصه الإنفاق.\nوإذا تزاحم عليه قوم ثلم بعضهم حال بعض.\nوالعلم بالضد 0 فهو باق دائم.\nويزكو على النفقة، ولا يثلم تناول البعض حال الباقين، وإلى هذا ذهب بعض المحققين فقال: ﴿وَمِمَّا رَزَقۡنَٰهُمۡ يُنفِقُونَ﴾⟪2:3⟫ أي: مما خصصناهم به\n⟦1:83⟧\nمن أنوار المعرفة يفيضون \" فعلى هذا عام في كل ذلك."}, {"a": [4, 5], "v": 1, "p": 83, "ev": 1, "ep": 86, "sid": 84, "t": "قوله تعالى: ﴿وَٱلَّذِينَ يُؤۡمِنُونَ بِمَآ أُنزِلَ إِلَيۡكَ وَمَآ أُنزِلَ مِن قَبۡلِكَ وَبِٱلۡأٓخِرَةِ هُمۡ يُوقِنُونَ﴾⟪2:4⟫.\nسورة البقرة: الآية (4) ..\nالإنزال، والوحي متقاربان، لكن استعمال \" الإنزال \" على اعتبار حال المنزل والمنزل إليه بالشرف والمنزلة، لا بالمكان، والوحي: هو الإشارة والإبقاء.\nوذلك على ثلاثة أضرب بينها الله تعالى في قوله «وما كان لبشر أن يكلمه الله إلا وحيا أو من وراء حجاب أو يرسل رسولا فيوحي بإذنه ما يشاء إنه» الأول - من ذلك الوحي: والإنزال الذي بينه تعالى وبين أولي العزم من الرسل بسفير يرونه.\nوالثاني: بسماع من غير رؤية، كحال موسى - عليه السلام - في ابتداء بعثته.\nوالثالث: بالإلهام والإلقاء في الروع.\nوذلك ضربان: إما الإلقاء في الروع في حال اليقظة، وهو المعبر عنه بالمحدث و \" المروع \"، وعليه نبه عليه السلام بقوله: (إن في أمتي لمروعين) وقوله: (إن يك في هذه الأمة محدث فعمر بن الخطاب) وقوله (إن روح القدس نفث في روعي) وإما إلقاء إليه في المنام، وذلك ضربان: إما ظاهر من المنام لا يحتاج إلى تعبير ...\nوإما تلويح ورمز يحتاج إلى تعبيره، ولهذا قال عليه السلام:\n\" الرؤيا الصادقة [الصالحة] جزء من خمس وأربعين جزءا من النبوة \" فالذي يكون في المنام بالإلقاء في الروع، قد يكون لغير الأنبياء - عليهم السلام - والذي يكون بالسماع من غير رؤية قد يكون لغير أولي العزم من الرسل.\nوالذي يكون بالسفير المرئي لا يكون إلا لأولي العزم.\nوعلى هذا\n⟦1:84⟧\nحال الإنزال، فقد ذكر تعالى: ﴿ٱللَّهُ ٱلَّذِيٓ أَنزَلَ ٱلۡكِتَٰبَ بِٱلۡحَقِّ وَٱلۡمِيزَانَۗ﴾⟪42:17⟫، وقال: ﴿وَأَنزَلَ لَكُم مِّنَ ٱلۡأَنۡعَٰمِ ثَمَٰنِيَةَ أَزۡوَٰجٖۚ﴾⟪39:6⟫ وقوله: ﴿وَأَنزَلۡنَا ٱلۡحَدِيدَ فِيهِ بَأۡسٞ شَدِيدٞ﴾⟪57:25⟫ ومعلوم أن ذلك بالتمكين والإلقاء في الروع: بالهداية إليه.\nواليقين أقوى إدراكات العقل، ولهذا قيل: هو مشاهدة الغيوب بعين القلوب تنبيه أنه أقوى إدراكات العقل، كما أن رؤية البصر أقوى إدراكات الحواس، ولصعوبة إدراكه، قال - عليه السلام -: \" أخوف ما أخاف على أمتي ضعف اليقين \" ولذلك قالوا: اليقين هو اطمئنان القلب اعتبارا بثمرته.\nوقال تعالى: ﴿وَكَذَٰلِكَ نُرِيٓ إِبۡرَٰهِيمَ مَلَكُوتَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَلِيَكُونَ مِنَ ٱلۡمُوقِنِينَ﴾⟪6:75⟫ واستعمل فيه \" الرؤية تنبيها على ما تقدم، والكلام في ترتيب الآيتين ونظمها صعب.\nوذاك أنه إن كانت تفصيلا للمتقين، فالوجه أن يفصل ذلك بفصل لا يدخل أحد القسمين في الآخر، نحو أن يقال: العرب بدوي وحضري، وشاعر وغير شاعر.\nأو تميمي وغير تميمي، فأما أن يقال: شاعر وتميمي، فلا يصح، ومعلوم أن بعض ما ينطوي عليه أحد الآيتين داخل في جملة الأخرى.\nوإن كان ذلك ليس بتفصيل، وإنما هي صفات للمتقين، ويكون ذكر بعض ذلك مخصصا عن الجملة كذكر جبرائيل وميكائيل بعد الملائكة على سبيل التخصيص، فالوجه: أن لا يعاد \" الذين \" ثانيا، [ثم] قوله: ﴿أُوْلَٰٓئِكَ عَلَىٰ هُدٗى مِّن رَّبِّهِمۡۖ وَأُوْلَٰٓئِكَ هُمُ ٱلۡمُفۡلِحُونَ﴾⟪2:5⟫ الآية: (5) - سورة البقرة.\n[يجب أن يعلم هل هما صفتان لموصوفين أو لموصوف واحد] فيقال - وبالله التوفيق: إنه قد قيل: الآيتان - وإن كانتا عامتين فمعناهما خاص.\nفالأولى أشير بها إلى الذين آمنوا عن الشرك، والثانية إلى الذين آمنوا من أهل الكتاب - وهو قول ابن عباس - واستدل على تقوية ذلك بأنه كما صنف الكفار - بعد\n⟦1:85⟧\nذلك - فجعلهم \" مجاهدا \" و \" منافقا \"، كذلك صنف المؤمنين، فجعلهم مؤمنا عن شرك، ومؤمنا عن غير مخالف في النبوة.\nفعلى هذا قوله: ﴿وَٱلَّذِينَ يُؤۡمِنُونَ بِمَآ أُنزِلَ إِلَيۡكَ﴾⟪2:4⟫ كأنه قيل: هذا الكتاب هدى للمسلمين الذين هذا وصفهم.\nولأهل الكتاب الذين جمعوا بين الإيمان بك وبمن تقدمك.\nوقد قيل فيه قول ثان: وهو أن الإيمان ضربان: ضرب يمكن أن يدرك جملتها بالعقل، وإن لم يكن إدراك تفاصيله إلا بالشرع.\nوذلك ثلاثة أشياء.\nذكرها في الآية المتقدمة: وهي أفضل ما يؤدي بالجوارح وهي الصلاة.\nوأفضل ما يؤدي من الأملاك، وهو الزكاة.\nوذلك صفات المتقين.\nثم ذكر بعد ذلك ثلاثة أشياء.\nذكرها في الآية المتقدمة: وهي أفضل ما يؤدي بالجوارح وهو الصلاة.\nوأفضل ما يؤدى من الأملاك، وهو الزكاة.\nوذلك صفات المتقين.\nثم ذكر بعد ذلك ثلاثة أحوال من أسرار الإيمان مما لا سبيل إلى معرفته إلا بالسمع وهو الإيمان بالقرآن والإيمان بالكتب المنزلة على الرسل المتقدمة الإيقان بيوم القيامة قال: وإنما أعاد \" الذين \" تنبيها أن هذه الثلاثة سبيلها غير سبيل الأول، وقد قيل فيه قول ثالث: وهو أن الإيمان ضربان، ضرب هو معرفة سبيل الحق، وطلب الوسيلة إليه وهو المشار إليه بقوله: ﴿ٱدۡعُ إِلَىٰ سَبِيلِ رَبِّكَ بِٱلۡحِكۡمَةِ وَٱلۡمَوۡعِظَةِ ٱلۡحَسَنَةِۖ﴾⟪16:125⟫ وبقوله: ﴿وَٱبۡتَغُوٓاْ إِلَيۡهِ ٱلۡوَسِيلَةَ﴾⟪5:35⟫ وضرب هو مزاولة السلوك إليه المشار [إليه] بقوله تعالى: ﴿قُلۡ هَٰذِهِۦ سَبِيلِيٓ أَدۡعُوٓاْ إِلَى ٱللَّهِۚ عَلَىٰ بَصِيرَةٍ أَنَا۠ وَمَنِ ٱتَّبَعَنِيۖ﴾⟪12:108⟫ وبقوله: ﴿وَجَٰهِدُواْ فِي ٱللَّهِ حَقَّ جِهَادِهِۦۚ﴾⟪22:78⟫ فالمعنيون بالآية الأولى هم الموطئون السبيل إليه بالإيمان به والعبادات البدنية والمالية، وبالثانية المجتهدون في التوصل إليه وهم الذين يعرفون حقائق مراد الله بما أنزله على أنبيائه وعناهم الله تعالى بقوله: ﴿وَهُدُوٓاْ إِلَى ٱلطَّيِّبِ مِنَ ٱلۡقَوۡلِ وَهُدُوٓاْ إِلَىٰ صِرَٰطِ ٱلۡحَمِيدِ﴾⟪22:24⟫ وبقوله: ﴿أَفَمَن شَرَحَ ٱللَّهُ صَدۡرَهُۥ لِلۡإِسۡلَٰمِ فَهُوَ عَلَىٰ نُورٖ مِّن رَّبِّهِۦۚ﴾⟪39:22⟫ وبقوله: ﴿أُوْلَٰٓئِكَ كَتَبَ فِي قُلُوبِهِمُ ٱلۡإِيمَٰنَ﴾⟪58:22⟫ وهم المزيد لهم بقوله: ﴿وَمَن يَقۡتَرِفۡ حَسَنَةٗ نَّزِدۡ لَهُۥ فِيهَا حُسۡنًاۚ﴾⟪42:23⟫ فعلى\n⟦1:86⟧\nهذا يرجع قوله تعالى: ﴿أُوْلَٰٓئِكَ عَلَىٰ هُدٗى مِّن رَّبِّهِمۡۖ﴾⟪2:5⟫ إلى الصنف الأول، ﴿وَأُوْلَٰٓئِكَ هُمُ ٱلۡمُفۡلِحُونَ﴾⟪2:5⟫ إلى الصنف الثاني، قوله تعالى: ﴿أُوْلَٰٓئِكَ عَلَىٰ هُدٗى مِّن رَّبِّهِمۡۖ وَأُوْلَٰٓئِكَ هُمُ ٱلۡمُفۡلِحُونَ﴾⟪2:5⟫ (5)\nقد تقدم القول في ذكر الهداية بما أغنى عن الإعادة.\nفأما \" الفلح \" فأصله: الشق ومنه قيل: \" الحديد بالحديد يفلح \" وسمى \" الأكار \" فلاحا، اعتبارا بمبدأ فعله، وهو شق الأرض، ومن قال: يسمى \" المكارى \" فلاحا لقول الشاعر \" وفلاح يسوق لها حمارا \" فهذا سوء نظر منه، فإنه أراد أكارا يسوق حمارا، فكما أنه لو قال: أكارا يسوق حمارا، لم يكن يجب أن يقال: الاكار: هو المكاري، كذلك هذا.\nوسمي \" الظفر \" فلاحا اعتبارا بكشف الكربة.\nثم \" الفلاح \" تارة يعتبر بأعراض الدنيا، فيقال: أفلح فلان: إذا ظفر بما يريده.\nوقول من قال: الفلاح: البقاء، لقول الشاعر: وترجو والفلاح بعد عاد وحميرا فإنما عني الفرج.\nوالبقاء: بعض الفرج.\nفإذا ذلك عام موضوع موضع خاص.\nوقد استعمل \" الفلاح \" في الآية لما هو في الحقيقة ظفر وفرج، كما قال عليه السلام: \" لا عيش إلا عيش الآخرة \" وهو قوله تعالى: ﴿وَإِنَّ ٱلدَّارَ ٱلۡأٓخِرَةَ لَهِيَ ٱلۡحَيَوَانُۚ﴾⟪29:64⟫."}, {"a": [6], "v": 1, "p": 87, "ev": 1, "ep": 89, "sid": 88, "t": "قوله - عز وجل - ﴿إِنَّ ٱلَّذِينَ كَفَرُواْ سَوَآءٌ عَلَيۡهِمۡ ءَأَنذَرۡتَهُمۡ أَمۡ لَمۡ تُنذِرۡهُمۡ لَا يُؤۡمِنُونَ﴾⟪2:6⟫ الآية: (6) - سورة البقرة\nالكفر في اللغة الستر، ووصف الليل بالكافر لستره الأشخاص والزارع لستره البذر في الأرض وليس لهما باسم كما ظن بعض أهل اللغة لما سمع قول الشاعر: ألقت ذكاء يمينها في كافر فإن ذلك على إقامة الوصف تمام المصوف، وقول الشاعر: كالكرم إذ نادى من الكافور، أي: الأكمام منه، وسمى القرية كفرا لذلك، وكفر النعمة: سترها، يقال: كفر كفرا وكفورا، نحو شكر شكرا وشكورا وهو كافر وكفور، وشاكر وشكور.\nوحقيقة الكفر ستر نعم الله تعالى، ولما كانت نعمه تعالى بالقول المجمل ثلاثا، نعمة خارجة: كالمال والجاه، ونعمة بدنية: كالصحة والقوة، ونعمة نفسية: كالعقل والفطنة، صار الشكر والفكر ثلاثة أنواع بحسبها، وأعظم الكفر ما كان مقابلا للنعمة [النفسية] فيها يتوصل إلى الإيمان واستحقاق الثواب، ومن قابل تلك النعم بالكفران فهو الكافر المطلق، ولذلك صار الكفر في الإطلاق جحود الوحدانية والنبوة والشريعة ..\n، وقوله تعالى: «سواء» في الأصل مصدر كالعلاء والنماء، وفي المتعارف يستعمل في وسط الشيء المعتبر استواؤه بطرفيه، ومنه سواء الدار، وأما السيان: ففي الشيئين المعتبر أحدهما بالآخر في المساواة، فالشيء هو المساوي كالقتل والمثل في معنى المقاتل والمماثل، فإذا قيل: \" سيان زيد وعمر \"، فمعناه: \" كل واحد منهما مساو للآخر \"، وإنما جاز قولهم: ([سواء] على أقمت أم قعدت) منه بإبهام الأمر على استواء الحالين لديه، وإن كان القصد الأول بهذا الكلام إلى الاستفهام دون المساواة، فلما صار فيه معنى الاستواء، جاز أن يقال ذلك بمعنى أن ما اقتضاه هذا السؤال سوى عندي، وأكثر النحويين جعلوا \" سواء \" مبتدأ وما بعده خبره، وقالوا: \" كل جملة حصلت خبرا لمبتدأ فلابد من أن يكون فيها ضمير منطوق به، أو مقدر إلا هذه الجملة، فإنه لا ضمير فيها بوجه، وذكر بعضهم أن المبتدأ ههنا مقدر، وقد دل عليه لفظ الاستفهام وسواء: خبره فالجملة قد تدل على المخبر عنه نحو من كذب\n⟦1:88⟧\nكان شرا له أي كان الكذب شرا له، وهذا التقدير أجود لأمور منها: أنه لا ينكسر الباب على هذا، لأن الباب مقرر في أن الجملة إذا كانت خبرا فلابد لها من ضمير يرجع إلى المخبر عنه، والثاني: أنا إذا قلنا: \" سواء عليهم القيام والقعود \" يخبر عن القيام والقعود بالسواء لا عن السواء بالقيام والقعود والثالث: إن سواء نكرة غير موصوفة ولا محدودة، فيقبح الابتداء به، وقال أبو على الغنوي في نصرة المذهب الأول: \" إنك إذا قلت سواء هو خبر، بقى الكلام بلا مبتدأ فالجملة بعده خبر ساقط على التقدير المتقدم ويشهد لصحة ما قلنا قولهم: \" تسمع بالمعيدي خير من أن تراه، فإن قولهم: \" تسمع \" يدل على مبتدأ، وقولهم: \" خير \" خبره، كأنه قيل: \" تسمع وسماعك بالمعيدي خير \"، والإنذار إخبار فيه تخويف، كما أن التبشير إخبار فيه سرور، وقولهم: نذرت يقتضي معنى خشيت وخفت، وأما قولهم: \" أنذرت \"، فذلك تقديم قول يقتضي خوفا من محذور أو رجاء لسرور.\nإن قيل: كيف قال ﴿سَوَآءٌ عَلَيۡهِمۡ﴾⟪2:6⟫ الآية وقد علم أنه قد آمن من الذين كفروا قوم قيل: إيمان من آمن لا ينافي مقتضى الآية، وذلك أنه تعالى نفى أنهم ينتفعون بالإنذار مع حصول الكفر، فأما إذا زال الكفر وهو الجحود، فإنه لا يمتنع أن ينتفعوا بالإنذار، كقولك: \" المريض سواء أطعمته أم لم تطعمه لا ينفعه الطعام \" - تنبيها أنه ما دام مرضه حاصلا لم ينفعه ذلك، ولا تقتضي أنه لا ينتفع بذلك إذا زال مرضه، وقد تقدم أن الطب ضربان: إزالة المرض، وحفظ الصحة، وأن الإنذار يجري مجرى الغداء الحافظ للصحة، وأن النظر في الأدلة المقتضية للتوحيد وإثبات الرسل جار مجرى الدواء المعيد للصحة، والمريض لا ينتفع بالغذاء ما لم يزل مرضه، فتبين أن الذي في قلبه مرض من الكفر لا ينتفع بما يجري مجرى الغذاء ما دام به المرض، وقد روى عن ابن عباس - رضي الله تعالى عنهما - ما دل على هذا، وهو أنه قال: \" عنى به الجاحدين لنعمه \" وأن الإنذار لا ينفعهم مع كفرهم \"، وقيل: إن ذلك حكم على جميعهم، لأن النبي - عليه السلام - كان يحب أن يؤمنوا بأجمعهم، وإيمان بعضهم ليس يقتضي أن الحكم على الكل كاذب، وقيل: الآية نزلت في اليهود الذين حجدوا نبوة النبي - صلى الله عليه وسلم - مع ظهور المعجزات لهم، ولم يؤمن أحد منهم، وقال الربيع: \" نزلت في قادة الأحزاب الذين نزلت فيهم.\n⟦1:89⟧\nقوله تعالى: ﴿أَلَمۡ تَرَ إِلَى ٱلَّذِينَ بَدَّلُواْ نِعۡمَتَ ٱللَّهِ كُفۡرٗا وَأَحَلُّواْ قَوۡمَهُمۡ دَارَ ٱلۡبَوَارِ﴾⟪14:28⟫ وقيل: لم يدخل في الإسلام منهم إلا نفر لا يدري هل حصل لهم الإيمان الموصوف في قوله تعالى: ﴿إِنَّمَا ٱلۡمُؤۡمِنُونَ ٱلَّذِينَ إِذَا ذُكِرَ ٱللَّهُ وَجِلَتۡ قُلُوبُهُمۡ وَإِذَا تُلِيَتۡ عَلَيۡهِمۡ ءَايَٰتُهُۥ زَادَتۡهُمۡ إِيمَٰنٗا﴾⟪8:2⟫\nفإن قيل: إذا علم أنه لا ينجع فيهم الإنذار، فما فائدة حث النبي - صلى الله عليه وسلم - على إنذارهم؟\nقيل: قد بين الله تعالى في الآية ما هو تنبيه على الجواب عن ذلك، لأنه قال: \" سواء عليهم \"، ولم يقل: عليك، ليبقى للنبي فضل الإنذار والسعي، ففي إبلاغه فائدتان: فائدة له في استحقاق الثواب لما تكلفه من المشاق، وفائدة لهم أن قبلوا، فهم وإن حرموا فائدة القبول، فإنه - عليه السلام - لم يحرم فائدة الإبلاغ، وعلى ذلك قال: ﴿سَوَآءٌ عَلَيۡهِمۡ أَسۡتَغۡفَرۡتَ لَهُمۡ أَمۡ لَمۡ تَسۡتَغۡفِرۡ لَهُمۡ لَن يَغۡفِرَ ٱللَّهُ لَهُمۡۚ﴾⟪63:6⟫ تنبيها على هذا المعنى، وقال فيما خاطب به الكفار وذمهم لعبادتهم الأصنام ﴿سَوَآءٌ عَلَيۡكُمۡ أَدَعَوۡتُمُوهُمۡ أَمۡ أَنتُمۡ صَٰمِتُونَ﴾⟪7:193⟫ فقال عليكم لما كان ذلك راجعا إلى الداعين دون المدعوين وخبر أن يصح أن يكون قوله: ﴿لَا يُؤۡمِنُونَ﴾⟪2:6⟫ وقوله: ﴿سَوَآءٌ عَلَيۡهِمۡ﴾⟪2:6⟫ مع خبره اعتراض في موضع الحال، ويصح أن يكون الجملة التي هي سواء عليهم مع خبره خبر \" إن \" وقوله: ﴿لَا يُؤۡمِنُونَ﴾⟪2:6⟫ حال مؤكدة، أو تفسير لذلك، لأنه إذا قيل: ﴿سَوَآءٌ عَلَيۡهِمۡ ءَأَنذَرۡتَهُمۡ أَمۡ لَمۡ تُنذِرۡهُمۡ﴾⟪2:6⟫ لا يعلم من ظاهره أن هذا الاستواء هل هو في: \" أن يؤمنوا \" أو في \" أن لا يؤمنوا \" فبين ذلك"}, {"a": [7], "v": 1, "p": 89, "ev": 1, "ep": 93, "sid": 90, "t": "قوله - عز وجل -: ﴿خَتَمَ ٱللَّهُ عَلَىٰ قُلُوبِهِمۡ وَعَلَىٰ سَمۡعِهِمۡۖ وَعَلَىٰٓ أَبۡصَٰرِهِمۡ غِشَٰوَةٞۖ وَلَهُمۡ عَذَابٌ عَظِيمٞ﴾⟪2:7⟫ الآية (7) سورة البقرة.\nالختم، والطبع الأثر الحاصل على نقش، وتجوز به في أمور، يقال: \" ختمت كذا \" في الاستيثاق من الشيء والمنع منه - نظرا إلى ما يحصل من المنبع بالختم على الكتب والأبواب، ويقال ذلك، ونعني به تحصل أثر نظر إلى النقش الحاصل عن الطابع إذا طبع، ويقال ذلك ونعني به بلوغ أخر الشيء - نظرا إلى أنه أخر فعل يفعل في إحراز الشيء منه، ومنه قيل: \" ختمت القرآن \" ويقال ذلك لما يستدل به إلى الشيء نظرا إلى ختم المناشر المستدل به على منشيها، وأما المراد من الآية، فقد قيل: \" للإنسان بالقول المجمل ثلاثة\n⟦1:90⟧\nأنواع من الذنوب يقابلها في الدنيا ثلاث عقوبات.\nالأول: الغفلة عن العبارات، وذلك يورث صاحبها جسارة على ارتكاب الذنوب، وهي المشار إليها بقوله عليه السلام: \" إن المؤمن إذا أذنب ذنبا كان نكتة سوداء في قلبه، فإن تاب ونزع واستغفر صقل قلبه، وإن زاد زادت حتى يغلق قلبه \" \" والثاني: الجسارة على ارتكاب المحارم، إما الشهوة تدعوه إليه أو وشرارة تحسنه في عينه، وذلك يورثه وقاحة، وهي المعبر عنها بالرين في قوله تعالى: ﴿كـَلَّاۖ بَلۡۜ رَانَ عَلَىٰ قُلُوبِهِم مَّا كَانُواْ يَكۡسِبُونَ﴾⟪83:14⟫ والثالث: الضلال، وهو أن يسبق إلى اعتقاد مذهب باطل، وأعظمه الكفر، فلا يكون منه تلفت بوجه إلى الحق، وذلك يورثه هيئة تمرنه على استحسانه للمعاصي واستقباحه للطاعات، وهو المعبر عنه بالختم والطبع، وكما عبر عنه بذلك في قوله تعالى: ﴿وَخَتَمَ عَلَىٰ سَمۡعِهِۦ وَقَلۡبِهِۦ﴾⟪45:23⟫ وقوله: ﴿أُوْلَٰٓئِكَ ٱلَّذِينَ طَبَعَ ٱللَّهُ عَلَىٰ قُلُوبِهِمۡ وَسَمۡعِهِمۡ وَأَبۡصَٰرِهِمۡۖ﴾⟪16:108⟫ فقد عبر عنه بالإقفال في قوله تعالى: ﴿أَمۡ عَلَىٰ قُلُوبٍ أَقۡفَالُهَآ﴾⟪47:24⟫ وبالإغفال في قوله: ﴿وَلَا تُطِعۡ مَنۡ أَغۡفَلۡنَا قَلۡبَهُۥ عَن ذِكۡرِنَا﴾⟪18:28⟫ وبقساوة القلب في قوله: ﴿وَجَعَلۡنَا قُلُوبَهُمۡ قَٰسِيَةٗۖ﴾⟪5:13⟫ وبجعل أكنة عليها في قوله: ﴿وَجَعَلۡنَا عَلَىٰ قُلُوبِهِمۡ أَكِنَّةً أَن يَفۡقَهُوهُ﴾ وبعدم العقل في آيات كثيرة.\nويجب أن يتصور ههنا نكتة تزيل الشبهة فيها وفيما أشبهها من الآيات، وهي أن الهداية من الله تعالى ضربان، أحدهما: بالعقل الذي هو فطرته التي فطر الناس عليها، ومتى توهم نفيا مرتفعا ارتفع التكليف، والثاني: العلم المحصل للإنسان بالفكر والروية بواسطة ما أعطى من نور الهداية الأولى، وهو الذي أشار إليه النبي - صلى الله عليه وسلم - فيما قال لعلي - رضي الله تعالى عنه - \" إذا تقرب الناس إلى خالقهم بالصلاة والصيام، فتقرب أنت إليه بالعقل تسبقهم بالدرجات \" فإذا كان كذلك، وجب أن يكون متصورا أن هذه الهداية الثانية مباحة للكافة.\n⟦1:91⟧\nكان لا سبيل إلى لقائها وتناولها والانتفاع بها إلا لمن جلى بصيرته لرؤيتها، وطهر قلبه بقبولها، وقد نبه تعالى على ذلك بقوله: ﴿قَدۡ أَفۡلَحَ مَن تَزَكَّىٰ﴾⟪87:14⟫ والكافر من حيث لم يجل البصيرة لم يرها، وإذا لم يرها لم يتناولها، وإذا لم يتناولها، صح أن يقال: \" هو ممنوع منها ومصروف عنها \"، كما قال تعالى: ﴿سَأَصۡرِفُ عَنۡ ءَايَٰتِيَ ٱلَّذِينَ يَتَكَبَّرُونَ فِي ٱلۡأَرۡضِ بِغَيۡرِ ٱلۡحَقِّ وَإِن يَرَوۡاْ كُلَّ ءَايَةٖ لَّا يُؤۡمِنُواْ بِهَا وَإِن يَرَوۡاْ سَبِيلَ ٱلرُّشۡدِ لَا يَتَّخِذُوهُ سَبِيلٗا وَإِن يَرَوۡاْ سَبِيلَ ٱلۡغَيِّ يَتَّخِذُوهُ سَبِيلٗاۚ﴾⟪7:146⟫ ثم بين سببه فقال: ﴿ذَٰلِكَ بِأَنَّهُمۡ كَذَّبُواْ بِـَٔايَٰتِنَا وَكَانُواْ عَنۡهَا غَٰفِلِينَ﴾⟪7:146⟫ وتصور بعض الناس أن ذلك الختم منع من الله تعالى للكافر عن الإيمان، واستدل به على جواز تكليف ما لا يستطاع، وهذا تصور فاسد، فالإنسان في هذه الحالة، وإن كان لا سبيل له إلى الإيمان في الحال، فذلك بما كسبت يداه من إهمال نفسه، فما فسد بينهما من يده، فإنه وإن كان لا يقدر على رده، فقد كان من قبل سهلا عليه أن يضبطه فلا يرمي به، ألا ترى أنه تعالى قال: ﴿ذَٰلِكَ بِأَنَّهُمۡ ءَامَنُواْ ثُمَّ كَفَرُواْ فَطُبِعَ عَلَىٰ قُلُوبِهِمۡ﴾⟪63:3⟫ فجعل الكفر علة للطبع على قلوبهم، وقال بعض المتكلمين: إن الختم والكن لو كان مانعا من الإيمان، لما أنكر الله تعالى على الكفار حيث قالوا ﴿وَقَالُواْ قُلُوبُنَا غُلۡفُۢۚ بَل لَّعَنَهُمُ ٱللَّهُ بِكُفۡرِهِمۡ فَقَلِيلٗا مَّا يُؤۡمِنُونَ﴾⟪2:88⟫ ﴿وَقَالُواْ قُلُوبُنَا فِيٓ أَكِنَّةٖ مِّمَّا تَدۡعُونَآ إِلَيۡهِ وَفِيٓ ءَاذَانِنَا وَقۡرٞ وَمِنۢ بَيۡنِنَا وَبَيۡنِكَ حِجَابٞ﴾⟪41:5⟫ وليس بصحيح استدلاله، وذاك أن هذا المنع حاصل، لكن هو من جهتهم على ما تقدم، والقوم لم يتصوروا ذلك، فلذلك أنكر الله عليهم ما قالوه، وأما ما قاله أبو علي الجبائي في أن \" الختم \" سمة جعلها الله تعالى في قلوب الكفار دلالة للملك على كفرهم كالكتابة في قلوب المؤمنين ليعرفوا بها الاعتقادات التي لا تظهر بالجوارح، فإن هذا كما قال الشاعر :\nتخرصا وأحاديثا ملفقة. . . ليست بنبع إذا عدت ولا غرب\nوذاك أن هذا الحكم لا سبيل إلى إثباته إلا بسمع غير محتمل، وأيضا فإن هذه الكتابة إن كانت\n⟦1:92⟧\nمحسوسة، فمن حقها أن يدركها ذو الحاسة وإن كانت معقولة، والاعتقاد أيضا معقول، فالملائكة غير مفتقرة في شيء من المعقولات إلى الأدلة والبراهين كما يحتاج إليها البشر، وقال أبو القاسم البلخي: \" إن ختم الله عليها شهادته على صاحبها بأنه لا يؤمن \" قال: وتخصيص القلب بذلك لاختصاصه بالاعتقادات، كتخصيص الرجل بالمشي، واليد بالبطش إذا قيل: \" مشت رجله \"، و \" بطشت يده \" وقد جعل الله تعالى في قوله: ﴿أُوْلَٰٓئِكَ ٱلَّذِينَ طَبَعَ ٱللَّهُ عَلَىٰ قُلُوبِهِمۡ وَسَمۡعِهِمۡ وَأَبۡصَٰرِهِمۡۖ﴾⟪16:108⟫ ثلاثتها مطبوعا عليها، وفي هذه الآية، وفي قوله: ﴿وَخَتَمَ عَلَىٰ سَمۡعِهِۦ وَقَلۡبِهِۦ وَجَعَلَ عَلَىٰ بَصَرِهِۦ غِشَٰوَةٗ﴾⟪45:23⟫.\nالبصر مغشي عليع مفردا عن القلب، والسمع، فقد قيل: إن ذلك لاختصاص البصر بمعنى، وهو أنه لما كان يحتاج في إدراك مدركاته إلة نور من خارج كما يحتاج إلى نور من داخل، والقلب والسمع يستوي حالهما في إدراك مدركاتها في الضوء والظلمة، خص البصر بالغشاوة - تنبيها على أن النور ممنوع منه، فلا يحصل به الانتفاع وأيضا، فإن ما يدركه القلب والسمع لا يختص بجهة دون جهة، وما يدركه البصر يختص بجهة المقابلة، فجعل ما يمنعهما من خاص، فعليهما الختم الذي يمنع من جميع الجهات، وجعل ما يمنع البصر من خاص الغشاوة المختصة بجهة دون جهة، وأكثر ما ذكر الله القلب، فالمقصود به \" العقل والمعرفة \"، وكان ذلك عباة عن الموعي بالوعاء، وعلى هذا قوله تعالى: ﴿إِنَّ فِي ذَٰلِكَ لَذِكۡرَىٰ لِمَن كَانَ لَهُۥ قَلۡبٌ﴾⟪50:37⟫، وقوله تعالى: ﴿فَتَكُونَ لَهُمۡ قُلُوبٞ يَعۡقِلُونَ بِهَآ﴾⟪22:46⟫، وقوله عليه السلام: \" استفت قلبك وإن افتاك المفتون \"، وأما إفراد السمع مع جمع القلب والبصر، فقد قيل: إن السمع في الأصل مصدر، فأجرى مجرى أصله، وقيل: أراد موضع سمعهم، وقيل: المضاف إلى الجمع يصح جمعه على الأصل، وإفراده على الإيجاز - اعتمادا على المضاف إليه، كقول الشاعر:\nأما عظمامها فبيض ...\nوأما جلدها فصليب\n⟦1:93⟧\nوالغشاوة: ما يغشى به كالعلاقة، وغشي منه، لكن قلب واوه ياء لنكسار ما قبله، وكذلك: غشيان، كغليان.\nومن نصب غشاوة فعلى تقديره جعل على أبصارهم غشاوة، ومن رفع فعلى القطع والاستئناف، والعذاب: اسم من التعذيب، وكان الأصل من قولهم ما عذب والتعذيب إزالة ذلك العذاب كقولهم مرضته فديته في إزالة المرض والقذى بين العذاب والعقاب أن العقاب لا يقال إلا فيما كان مجازة، وكأنه هو المتعقب للجرم المتقدم، والعذاب يقال فيه وفي غيره، ووصفه بالعظيم: تنبيه أنه إذا قويس بسائر ما يجانسه قصر جميعه عنه."}, {"a": [8], "v": 1, "p": 93, "ev": 1, "ep": 95, "sid": 94, "t": "قوله - عز وجل - ﴿وَمِنَ ٱلنَّاسِ مَن يَقُولُ ءَامَنَّا بِٱللَّهِ وَبِٱلۡيَوۡمِ ٱلۡأٓخِرِ وَمَا هُم بِمُؤۡمِنِينَ﴾⟪2:8⟫ الآية: (8) - سورة البقرة.\nالناس: جماعة حيوان ذي فكر وروية، واختلف في لفظه، فقيل: هو من قولهم: أناس، وحذف همزته وتقديره بعد الحذف عال، وقيل: بل هو من: \" ناس \" - ينوس - أي اضطرب، وتسميته بذلك لكونه ذا اضطراب زائد على غيره، إما ببدنه وفكره معا، فللإنسان بالفكر حركة زائدة على سائر الحيوان، وقيل: هو ومقلوب من: نسى، نحو: \" جذب \"، و \" جبذ \" ولاه أبوك ولهي أبوك، وكذا قال ابن عباس - رضي الله تعالى عنهما - في الإنسان: إنه سمى بذلك لأنه عهد إليه فنسى، فإنسان: على ذلك: \" أفعلان \" أصله \" إنسيان \" بدلالة تصغيرهم على أنيسان وقيل: سمي إنسا وإنسانا لانه خلق خلقه لا قوام له في حياته بجميع أسبابه، فيحتاج البعض إلى بعض ليتسبب لهم أمورهم ولأنه إذا لم يكن له مسكون إليه من جنسه لم تطب حياته، وعلى ذلك قال تعالى: ﴿وَجَعَلَ مِنۡهَا زَوۡجَهَا لِيَسۡكُنَ إِلَيۡهَاۖ﴾⟪7:189⟫ وهذا المعنى رمقه الشاعر حيث قال:\nمن كان في الدنيا بغير حبيب. . . فحياته فيها حياة غريب\nما كان في حور الجنان لا دم. . . لو لم يكن حواء من مرغوب\nقد كان في الفردوس يشكو وحشة. . . فيها فلم يأنس بغير حبيب\n⟦1:94⟧\nوقد روى أنه سمي إنسانا لأنه نسى العهد، وهذا من حيث اللفظ لا يصح، لكن من حيث المعنى يصح أن يقال: عنى أنه أنس بالشجرة، فنسى العهد والله أعلم، وأما القول: فيقال على أوجه: الأول: اللفظ المبرز بالعبادة، والثاني: للمعنى المتصور في النفس المعبر عنه باللفظ والثالث: للمذهب نحو: \" فلان يذهب إلى قول أبي حنيفة \" - رحمه الله تعالى -.\nوالرابع: للعناية الصادقة بالشيء نحو: فلان يقول بكذا، والخامس للدلالة المنبئة عن الشيء نحو: امتلأ الحوض، وقال قطني\nوالسادس: في استعمال المنطقيين عبارة عن الحد، يقولون قول الجوهر كذا، وقول العرض كذا، أي حدهما، ولاستعمال القول على أوجه مختلفة، قال تعالى: ﴿يَقُولُونَ بِأَفۡوَٰهِهِم﴾⟪3:167⟫ وقال: ﴿وَيَقُولُونَ فِيٓ أَنفُسِهِمۡ﴾⟪58:8⟫ والأصل في ذلك العبارة، لكن عبر عن نسبة تارة به كتسمية العنب خمرا في قوله تعالى: ﴿إِنِّيٓ أَرَىٰنِيٓ أَعۡصِرُ خَمۡرٗاۖ﴾⟪12:36⟫ والفرق بين القول والكلام أن الكلام لا يطلق إلا لجملة مفيدة لفظا أو تقديرا، والقول قد يقال لبعض الجملة، فإذا كل كلام قول، وليس كل قول كلاما، ولذلك قال سيبويه:\n\" قلت: في كلامهم: يحكى به ما كان كلاما لا قول \" فأورد ذلك مورد المقرر في النفس أن الكلام موضوع لجملة مفيدة، وقد بين الله تعالى في هذه الآية أن في الناس من يدعي الإيمان بالله والمعاد، وهو كاذب في قوله ودعاه وذلك كقوله: ﴿وَإِذَا جَآءُوكُمۡ قَالُوٓاْ ءَامَنَّا وَقَد دَّخَلُواْ بِٱلۡكُفۡرِ وَهُمۡ قَدۡ خَرَجُواْ﴾⟪5:61⟫ وقوله: ﴿يَقُولُونَ بِأَفۡوَٰهِهِم مَّا لَيۡسَ فِي قُلُوبِهِمۡۚ﴾⟪3:167⟫ كل ذلك تنبيه على أن الإيمان غير نافع ولا مقبول إلا بتقديم النية والإخلاص ومطابقة المقال والفعال، وقال أبو علي الجبائي: هذه الآية تدل على أن إقرار من أقر بالله إذا لم يكن عارفا بالله لا يكون بهذا القول مؤمنا بل مدعيا له.\nوالمخالف لا يخالف في ذلك وإنما يقول: إنه يصير مؤمنا إذا تفوه بالشهادتين، وقال أبو علي أيضا: \" إن الآية\n⟦1:95⟧\nتدل على بطلان قول من زعم أن جميع المكلفين عارفون بالله \" قال: لأن هؤلاء المنافقين لو كانوا بالله عارفين، وكانوا بحضرة النبي - عليه السلام - مقرين، لكان يجب أن يكون إقرارهم بذلك إيمانا منهم، لأن من عرف الله وأقر به لم يكن إقراره غير إيمان، فلما بين تعالى أنهم غير مؤمنين بما أخبروا به، علمنا أنهم لم يكونوا يعرفونه وليس في الآية دلالة على ما قال، أو لأن الله تعالى قال: يقولون آمنا بالله وباليوم الآخر، ثم نفى عنهم الإيمان بهما، واحد لا يقول: إن معرفة الإنسان بالله وباليوم الآخر ضرورة وإن ادعوا معرفة الله وحدها، وثانيا: أن أحدا لا يقول: \" الإقرار بالله على وجه الخداع إيمان، والله تعالى قد أخبر أنهم يخادعون الله بهذا القول، وثالثا: أن الإيمان المنفي عنهم ليس هو الإقرار، بل هو سكون النفس المذكور في قوله عز وجل: ﴿ٱلَّذِينَ ءَامَنُواْ وَتَطۡمَئِنُّ قُلُوبُهُم بِذِكۡرِ ٱللَّهِۗ﴾⟪13:28⟫.\nورابعا: أن من يقول: معرفة الله ضرورة، يذكر أن ذلك لا يحصل إلا عن سبب يتقدمه كالعلم بمخبر الأخبار المتواترة لا يحصل إلا بتقديم سماع المخصوص فكذلك معرفة الله ضرورة [لكن لابد فيها من سبب يتقدمها، وخامسها: أن عند كثير ممن يدعي] أن معرفة الله ضرورة أن ذلك موجود في الإنسان بالقوة، كوجود النار في الحجر، فلابد لها من انقداح به يخرج، ومتى لم يحصل السبب لم تكن النار، كذلك المعرفة بالله تعالى."}, {"a": [9], "v": 1, "p": 95, "ev": 1, "ep": 98, "sid": 96, "t": "قوله عز وجل: ﴿يُخَٰدِعُونَ ٱللَّهَ وَٱلَّذِينَ ءَامَنُواْ وَمَا يَخۡدَعُونَ إِلَّآ أَنفُسَهُمۡ وَمَا يَشۡعُرُونَ﴾⟪2:9⟫\nالآية (9) - سورة البقرة.\nالخداع: إنزال الغير عما هو بصدده بأمر تبديه على خلاف ما تخفيه، ومنه: قيل: خدع الضب.\nإذا استتر في جحره، واستعمال ذلك فيه لما اعتقدوا في الضب، أنه يعد عقربا يلدغ من يدخل يده في حجره حتى قالوا العقرب بواب الضب، ولاعتقاد الخديعة فيه قالوا: \" أخدع من ضب \" وطريق خادع مخالف لما يقتضيه ظاهره، والمخدع كأنك جعلته خادعا لمن رام تناول ما فيه لأنه بيت في بيت، وقولهم: \" خدع الطريق \" إذا قل، فتغير متصور منه هذا المعنى.\nوالاخدعان: تصور منهما الخداع، لاستنادهما تارة، وظهورهما أخرى، وفي الحديث:\n\" بين يدي الساعة سنون خداعة \" أي مغتالة، لتلونها بالجدب تارة، والخصب أخرى.\nإن قيل:\n⟦1:96⟧\nلم قال ﴿يُخَٰدِعُونَ ٱللَّهَ﴾⟪2:9⟫ وهم لم يقصدوا بفعلهم خديعته؟ قيل: ذكر بعض النحويين أنه أراد تعالى \" يخادعون رسول الله \"، فحذف المضاف، وهذا باعتبار حكم اللفظ دون المعنى فأما باعتبار المعنى فإنهم لما قصدوا خديعة النبي - عليه السلام - وقد أنبأ تعالى أن معاملة الله تعالى، حتى قال: ﴿مَّن يُطِعِ ٱلرَّسُولَ فَقَدۡ أَطَاعَ ٱللَّهَۖ﴾⟪4:80⟫ وقال: ﴿إِنَّ ٱلَّذِينَ يُبَايِعُونَكَ إِنَّمَا يُبَايِعُونَ ٱللَّهَ﴾⟪48:10⟫ جعلهم مخادعين له بخديعتهم النبي - صلى الله عليه وسلم -،\nفإن قيل: المخادعة من بين اثنين، وقد علم أن ذلك لم يكن من الله تعالى ولا من الرسول - صلى الله عليه وسلم -، فكيف قال يخادعون؟ قيل: قد قال أهل اللغة وكثير من المفسرين: أن الخديعة من الله هي مجازاته إياهم بمثل فعلهم، فسمي مجازاة الشيء باسمه، وكذلك قالوا في المكر والهزؤ ونحوهما مما وصف به نفسه، ولا يليق به، وعلى ذلك قول الشاعر:\nفنجهل فوق جهل الجاهلينا\nووجه أخر وهو أنه قد تقدم أن مخادعتهم لله - عز وجل - في الحقيقة مخادعة الرسول، ولما كانوا يراؤون ليزيل عنهم حكم المشركين ويجريهم في الأحكام مجرى المؤمنين، ويطلعهم على الأسرار، وهو لا يجريهم في كثير من الأمور مجراهم تصوروا أن ذلك لهم خداع، كما أن الأول منهم له خداع، فأخرج اللفظ على حسب وهمهم وجسبانهم فهمهم، لا على ما عليه حقيقة الأمر.\nوقد يطلق الحكم على المعنى عبارة على حسب اعتقاد المخاطب والمخبر عنه لأعلى ما عليه حقيقة الأمر كقوله تعالى: ﴿ذُقۡ إِنَّكَ أَنتَ ٱلۡعَزِيزُ ٱلۡكَرِيمُ﴾⟪44:49⟫ أي على زعمك، وقول الشاعر:\nخذها خذيف فأنت السيد الصمد ..\n⟦1:97⟧\nوما حكى الله تعالى عن موسى - عليه السلام - في قوله: ﴿وَٱنظُرۡ إِلَىٰٓ إِلَٰهِكَ ٱلَّذِي ظَلۡتَ عَلَيۡهِ عَاكِفٗاۖ﴾⟪20:97⟫\nفإن قيل: كيف وصف تعالى نفسه بأنه خادعهم في قوله: ﴿يُخَٰدِعُونَ ٱللَّهَ وَهُوَ خَٰدِعُهُمۡ﴾⟪4:142⟫؟ قيل هو على ما تقدم، ووجه آخر في هذا اللفظ، وإخوانه مما وصف الله تعالى نفسه به من الصفات التي تنزه تعالى عما يتصور من ظواهر معانيها نحو قوله تعالى: ﴿وَهُوَ شَدِيدُ ٱلۡمِحَالِ﴾⟪13:13⟫، وقوله: ﴿وَمَكَرُواْ مَكۡرٗا﴾ وقوله: ﴿فَلَا يَأۡمَنُ مَكۡرَ ٱللَّهِ إِلَّا ٱلۡقَوۡمُ ٱلۡخَٰسِرُونَ﴾⟪7:99⟫، وقوله: ﴿سَنَسۡتَدۡرِجُهُم مِّنۡ حَيۡثُ لَا يَعۡلَمُونَ ۝ وَأُمۡلِي لَهُمۡۚ إِنَّ كَيۡدِي مَتِينٌ﴾ كل ذلك قد قيل فيه قيول، من تصوره متحريا به الحقى ثلج قلبه، واستقرب ما كان من قبل يستبعده، وهو أن المكر والخديعة، وإنما هو استنزال الغير عما هو بصدده بأمر يبدي منه خلاف ما تخفيه ويتحراه مستعمله على وجهين: أحدهما: قاصدا به استنزال الغير عن ضلال إلى الرشد وذلك جميل، وهو كما يفعله الأب البار بابنه من تحذير يستجره به إلى ترك شرا أو تعاطي خير، فيقول: \" خدعت ابني عما كان يتعاطاه من القبيح \"، و \" مكرت به حتى قبحته في عينه \"، وقد علم أن هذا الفعل وإن أطلق عليه لفظ الخديعة والمكر فهو فعل حسن، فإذا المكر والخديعة وإن كان لفظهما مستبشعا فقد يقصد به وجه محمود، وبالعكس من ذلك فعل العدالة، فقد يتحراه الإنسان لاستغواء غيره وإضلاله مما يعد فسادا وجورا وخديعة ومكرا، قد يكون صلاحا ورشدا وعدلا، وما يعد صلاحا وعدلا ورشدا قد يكون فسادا وجورا ومكرا، وبهذا النظر قال بعض التابعين: \" كل قبيح من العبد فهو حسن من الله تعالى \" ويعني بذلك أن الفعل يقبح ويحسن المقاصد، ولهذا قال عليه السلام: \" الأعمال بالنيات ولكل أمرئ ما نوى \"، وقال: \" نية المؤمن خير من عمله \"، وبهذا النظر قال بعض المحققين وقد سئل عن شيء يقبح إطلاقة\n⟦1:98⟧\nفي الله تعالى مع ورود الشرع به، فأنشد:\nويقبح من سؤال الشيء عندي ...\nفتفعله فيحسن منك ذاكا\nفهذا ظاهر لمن جلى بصيرته وتأمل حقيقته، ونبه بقوله: ﴿وَمَا يَخۡدَعُونَ إِلَّآ أَنفُسَهُمۡ﴾⟪2:9⟫ أن وبال خديعتهم راجع على أنفسهم لا على الله تعالى وعلى المؤمنين، كقولك: \" ظلمت فلانا وما ظلمت إلا نفسك \"، وذلك في الحقيقة أعظم خديعة وظلم وجور، فإن الله تعالى لما قيض لهم النعيم الأبدي والخير السرمدي، وسهل لهم السبيل إليه، ثم غفلوا عنه، ومالوا إلى زهرات الدنيا، صاروا في الحقيقة خادعين لأنفسهم ظالمين لها، ولذلك وصفهم في القرآن بطلم أنفسهم في غير موضع وبأنهم خسروا أنفسهم وما يمركون إلا بأنفسهم، ولأنه قيل: \" من خدعك وقد عرفت خديعته فقد خدع نفسه \"، ومعلوم أن الله تعالى لا يخفى عليه شيء، فمن خادعه فقد خدع نفسه، وقوله: ﴿وَمَا يَشۡعُرُونَ﴾⟪2:9⟫ أصل هذا الشعر ومنه الشعار للثوب الذي يلي الجسد، فيقال: أشعرته ثوبا، ثم يقال على التشبيه بذلك أشعرهما، واستشعر سرورا، و \" شعرت كذا \": يستعمل على وجهين، تارة يؤخذ من مس الشعر، ويعبر به عن اللمس، وعنه استعمل المشاعر للحواس، فإذا قيل: \" فلان لا يشعر \" فذلك أبلغ في الذم من أنه لا يسمع ولا يبصر، لأن حس اللمس أعم من حس السمع والبصر، وتارة يقال: \" شعرت كذا \": أي أدركت شيئا دقيقا من قولهم: شعرته أي أصبت شعره نحو: قادته وراسته، وكأن ذلك إشارة إلى نحو قولهم: \" فلان يشق الشعر في كذا \" إذا دقق النظر فيه ومنه أخذ الشاعر لإدراكه دقائق المعاني ..."}, {"a": [10], "v": 1, "p": 98, "ev": 1, "ep": 100, "sid": 99, "t": "قوله تعالى: ﴿فِي قُلُوبِهِم مَّرَضٞ فَزَادَهُمُ ٱللَّهُ مَرَضٗاۖ﴾⟪2:10⟫ الآية: (10) - سورة البقرة.\nالمرض ضربان: جسمي ونفسي، وكلاهما خروج عن الاعتدال الخاص بهما، فالجسمي: معروف، والنفسي: كالجهل والجبن والبخل الوحسد والحرص وسائر الرذايل الخلقية وتسميتها بالمرض إما لكونها مانعة عن إدراك الفضائل، كالمرض الملنع للبدن عن التصرف الكامل، وأما لكونها ذريعة إلى سلب الحياة الحقيقة التي هي في الدنيا لسان صدق، وفي الآخرة بقاء الأبد، كما وصفه تعالى في قوله:\n⟦1:99⟧\n﴿وَإِنَّ ٱلدَّارَ ٱلۡأٓخِرَةَ لَهِيَ ٱلۡحَيَوَانُۚ﴾⟪29:64⟫، وأما الميل النفي به إلى الاعتقادات الرديئة ميل البدن المريض إلى الأشياء المضرة، ويكون هذه الأشياء بصورة المرض قيل: ذوي صدر فلان، ونقل قلبه، وقال عليه السلام: \" وأي داء أدوأ من البخل \"، وقوله تعالى: ﴿فِي قُلُوبِهِم مَّرَضٞ﴾⟪2:10⟫ عبارة عن نفاقهم وشكهم وعداوتهم، وقول ابن مسعود - رضي الله عنه والحسن وقتادة رحمهما الله تعالى: \" إنه شك، وقول غيرهم: إنه حب الدنيا واتباع الهوى، وقول آخر: إنه غم وآخر: إنه حسد، وآخر: إنه السكون إلى الدنيا، وكلها إشارات على سبيل المثال إلى أبغاض ما ينطوي عليه معنى المرض ولا خلاف بينهم فيه، فمعنى قوله: ﴿فَزَادَهُمُ ٱللَّهُ مَرَضٗاۖ﴾⟪2:10⟫ على أوجه، الأول كما تقدم: أن ما أنزله الله يجري من النفس مجرى الغذاء الحافظ للصحة، ومتى تناوله المريض الذي لم يزل مرضه لم ينفعه بل يضره، والثاني : أن هذه الزيادة في المرض هي ما كان الله تعالى يؤتيه نبيه والمؤنين من إنعامه ويصير زيادة في مرض المنافقين وذلك كقولك لمن أعطاك شيئا: \" قد أكمدت عدوي وهو لم يقصج إكماده، ولكن لما تولد من فعله بك ذلك صح نسبته إليه، وعلى ذلك قوله الشاعر:\nيا مرسل الريح جنوبا وصبا ...\nإن غضبت قيس فزدها غضبا\nأي زدنا إيلا ليزدادوا غضبا، وعلى ذلك قوله تعالى: ﴿وَأَمَّا ٱلَّذِينَ فِي قُلُوبِهِم مَّرَضٞ فَزَادَتۡهُمۡ رِجۡسًا﴾⟪9:125⟫، وقوله: ﴿وَلَيَزِيدَنَّ كَثِيرٗا مِّنۡهُم مَّآ أُنزِلَ إِلَيۡكَ مِن رَّبِّكَ طُغۡيَٰنٗا وَكُفۡرٗاۚ﴾، ولا يختلف المعنى في قوله تعالى: ﴿فَزَادَهُمُ ٱللَّهُ مَرَضٗاۖ﴾⟪2:10⟫ أي جعل مورده مورد خير أو مورد دعاء، فإن الدعاء من الله واجب، وإن كان منا رغبة وطلبا، ويجوز أن يكون ذلك رجعا إلى حال الآخرة، ومعناه من في قلبه مرض، فإن الله يزيده في الآخرة مرضا نحو قوله: ﴿وَمَن كَانَ فِي هَٰذِهِۦٓ أَعۡمَىٰ فَهُوَ فِي ٱلۡأٓخِرَةِ أَعۡمَىٰ وَأَضَلُّ سَبِيلٗا﴾⟪17:72⟫ وهذا والأول يرجعان إلى معنى، لأنهم إذا زيدوا في الدنيا عداوة للنبي - صلى الله عليه وسلم - ما ازدادوا إلا شكا في الآخرة استحقاق عذاب، قوله تعالى: ﴿وَلَهُمۡ عَذَابٌ أَلِيمُۢ بِمَا كَانُواْ يَكۡذِبُونَ﴾⟪2:10⟫\n⟦1:100⟧\n- أليم: بمعنى مؤلم نحو سميع وخصيب بمعنى مسمع ومخصب، وقوله: ﴿بِمَا كَانُواْ يَكۡذِبُونَ﴾⟪2:10⟫، أي بسبب كذبهم أو بدل كذبهم، كقولهم: هذا بذاك، وحجة من قرأ بالتخفيف أن ما قيله كذب، وهو قوله: ﴿وَمَا هُم بِمُؤۡمِنِينَ﴾⟪2:8⟫ وهو به أشبه، لأنه في صفة المنافقين، وقد قال الله تعالى فيهم ﴿وَٱللَّهُ يَشۡهَدُ إِنَّ ٱلۡمُنَٰفِقِينَ لَكَٰذِبُونَ﴾⟪63:1⟫، ومن قرأ \" يكذبون \"، فقوله: ﴿بَلۡ كَذَّبُواْ بِمَا لَمۡ يُحِيطُواْ بِعِلۡمِهِۦ﴾⟪10:39⟫، ولأن التكذيب أبلغ، إذ كل مكذب بشيء كاذب وليس كل كاذب مكذبا،"}, {"a": [11, 12], "v": 1, "p": 100, "ev": 1, "ep": 101, "sid": 101, "t": "وقوله تعالى: ﴿وَإِذَا قِيلَ لَهُمۡ لَا تُفۡسِدُواْ فِي ٱلۡأَرۡضِ قَالُوٓاْ إِنَّمَا نَحۡنُ مُصۡلِحُونَ﴾⟪2:11⟫ الآية (11) - سورة البقرة.\nالفساد: خروج الشيء عن الاعتدال، والصلاح على الضد منه، والافساد: إخراجه عن الاعتدال، والفساد عام في الكفر والضلال وكل ما هو ضار، والصلاح عام في الإيمان والرشد وكل نافع، فقوله: ﴿لَا تُفۡسِدُواْ فِي ٱلۡأَرۡضِ﴾⟪2:11⟫ عام في كل ذلك، وقول ربيعة وقتادة أن معناه \" لاتسالموا الكفار \"، ومثله: ﴿وَلَا تُفۡسِدُواْ فِي ٱلۡأَرۡضِ بَعۡدَ إِصۡلَٰحِهَا﴾، ومن قال: عنى بذلك كنز الدراهم، فإنه تمثيل بأدنى ما يكون فسادا - تنبيها أن ذلك عام، فإنه إذا كان ذلك فسادا، فما فوقه من قتل النفس الزكية بغير حق ونحوه أولى بذلك، والخطاب في الآية للمنافقين، وما روي عن سلمان أ، أهل هذه الآية لم يأتوا بعد، فيجوز أن يكون معنى قوله: \" أنه سيكون من بعد حاله من له في ذلك شبيهه بحال المنافقين، فإن الآية متصلة بما قبلها، والضمير فيها ليس إلا لمن تقدم ذكره، وقولهم ﴿إِنَّمَا نَحۡنُ مُصۡلِحُونَ﴾⟪2:11⟫ فيه تنبيه أنهم يتصورون إفسادهم بصورة الإصلاح لما في قلوبهم من المرض، كما قال: ﴿أَفَمَن زُيِّنَ لَهُۥ سُوٓءُ عَمَلِهِۦ فَرَءَاهُ حَسَنٗاۖ﴾⟪35:8⟫، وقوله: ﴿وَزَيَّنَ لَهُمُ ٱلشَّيۡطَٰنُ مَا كَانُواْ يَعۡمَلُونَ﴾⟪6:43⟫، وقوله: ﴿وَهُمۡ يَحۡسَبُونَ أَنَّهُمۡ يُحۡسِنُونَ صُنۡعًا﴾⟪18:104⟫ قال الحسن: من ذلك الإفساد: بناؤهم مسجد قباء ضرارا وكفرا وتفريقا بين المؤمنين وقوله - عز وجل - ﴿أَلَآ إِنَّهُمۡ هُمُ ٱلۡمُفۡسِدُونَ﴾⟪2:12⟫ \" ألا \": تقرير للإثبات لأن \" لا \" للنفي، والألف\n⟦1:101⟧\nللاستفهام، واجتماعهما يقتضي إثباتا نحو: \" أليس \" و \" الم \"،\nإن قيل: ما الذي يفيد تعريف قوله المفسدون وإدخال لفظه هم عليه؟.\nقيل: أما التعريف: فيقتضي كون الكلام جوابا أو كالجواب، وأما إدخال لفظ هم، فيقتضي إثبات الحكم للمذكور ونفيه عمن عداه نحو أن يقال: \" زيد منطلق \"، فتقول: أنت يا عمرو هو المنطق، ولما كان في قولهم: ﴿نَحۡنُ مُصۡلِحُونَ﴾⟪2:11⟫ تعريض إنكم المفسدون رد الله تعالى عليهم بقوله: ﴿أَلَآ إِنَّهُمۡ هُمُ ٱلۡمُفۡسِدُونَ﴾⟪2:12⟫ وقد تقدم أن \" شعرت \" يستعمل على وجهين أحدهما بمعنى: أحسست والثاني: بمعنى فطنت، فقوله: ﴿وَمَا يَشۡعُرُونَ﴾⟪2:9⟫ في الآية الأولى نفي الإحساس عنهم، وفي هذه الآية نفي الفطنة عنهم، لأن معرفة الصلاح والفساد تدرك بالفطنة، وفي الآية التي بعدهما نفي العلم عنهم،\nفإن قيل: كيف نفي أولا الحس ثم الفطنة ثم العلم ومعلوم أن ما لا حس له فلا فطنة له ولا علم؟، قيل: إن في نفي هذه الثلاثة على هذا الوجه تنبيها لطيفا ومعنى دقيقا وذلك أنه يبين في الأول أن في استعمالهم الخديعة نهاية للجمل الدالة على عدم الحس، ثم بين في الثاني أنهم لا يفطنون - تنبيها على أن ذلك لازم لهم، لأن من لا حس له لا فطنة له، ومن لا فطنة له لا علم له، ثم بين في الثالث أنهم \" لا يعلمون \" - تنبيها أن ذلك أيضا لازم لهم، لأن من لا فطنة له فلا علم له فإذا: من الألفاظ الثلاث إشارة إلى قياس ظاهر وإلزام واجب لمن تأملها وتدبرها."}, {"a": [13], "v": 1, "p": 101, "ev": 1, "ep": 102, "sid": 102, "t": "وقوله تعالى: ﴿وَإِذَا قِيلَ لَهُمۡ ءَامِنُواْ كَمَآ ءَامَنَ ٱلنَّاسُ قَالُوٓاْ أَنُؤۡمِنُ كَمَآ ءَامَنَ ٱلسُّفَهَآءُۗ أَلَآ إِنَّهُمۡ هُمُ ٱلسُّفَهَآءُ وَلَٰكِن لَّا يَعۡلَمُونَ﴾⟪2:13⟫ الآية: (13) - سورة البقرة.\nقولهم: الناس، بل كل اسم نوع، ف، ه يستعمل على وجهين، أحدهما: دلالة على المسمى وفصلا بينه وبين غيره، والثانيك وجود المعنى المختص به وذلك هو الذي يمدح به في نحو:\n\" إذ الناس ناس والزمان زمان \"\nونحو ذلك: \" زيد رجل \"، و \" هذا الفرس فرس \"، ومثال ذلك أن كل ما أوجده الله في هذا العالم يصلح لفعل خاص به لا يصلح لذلك العمل سواه، فإن الفرس للعدو الشديد، والبعير لقطع الفلاة البعيدة، والمنجر لنجر الخشب والمنحت لنحته، وعلى ذلك الجوارح كاليد والرجل والعين.\nوالإنسان أوجد لأن يعلم ويعمل بحسبه، وكل شيء لو يوجد كاملا لما قد خلق له لا يستحق اسمه مطلقا، بل قد ينفي عنه نحو قولهم: \" فلان ليس بانسان \"، أي لا يوجد فيه المعنى الذي خلق من أجله، فإذ ثبت ذلك، فقوله\n⟦1:102⟧\nتعالى: ﴿وَمِنَ ٱلنَّاسِ مَن يَقُولُ ءَامَنَّا بِٱللَّهِ﴾ هو اسم جنس لا غير، وقوله: ﴿كَمَآ ءَامَنَ ٱلنَّاسُ﴾⟪2:13⟫ معناه كما يفعل من وجد فيه تمام فعل الإنسانية الذي يقتضيه العقل والتمييز فإذا قول ابن عباس - رضي الله عنهما: إنه عنى كما آمن أصحاب النبي عليه السلام وقول غيره أنه عنى كما آمن أصحاب النبي عليه السلام وقول غيره أنه عنى كما أمن الذين أسلموا من اليهود مثل \" عبد الله بن سلام \".\nوأصحابه كلاهما صحيح، لأن الفريقين يجري على ما اقتضاه فعل الإنسانية، وقوله تعالى: ﴿قَالُوٓاْ أَنُؤۡمِنُ﴾⟪2:13⟫ استعلام على جهة النفي نحو ﴿أَنُطۡعِمُ مَن لَّوۡ يَشَآءُ ٱللَّهُ أَطۡعَمَهُۥٓ﴾⟪36:47⟫ ومعناه: لا نؤمن إيمان السفهاء تعريضا بأصحاب النبي - عليه السلام - والسفيه: خفة في البدن وفي المقال يقتضيها نقصان العقل، والحلم رزانة في البدن يقتضيها زيادة العقل، وعنه استعير \" زمام سفيه \"، و \" رمح سفيه \"،\nإن قيل: كيف عذرهم بأهم لا يعلمون؟ قيل لهم: ليس عذرا لهم، بل تعظيم أمر عليهم وأنهم مع جهلهم يجهلون جهلهم كما قال:\nجهلت ولم تعلم بأنك جاهل ...\nوذاك لعمري من تمام الجهالة\nوكل ما ذم به الكفار من أنهم لا يعلمون ولا يبصرون ولا يسمعون فتنبيه أنهم لم يستعملوا هذه الآلات ولم يتفكروا."}, {"a": [14], "v": 1, "p": 102, "ev": 1, "ep": 103, "sid": 103, "t": "وقوله - عز وجل -: ﴿وَإِذَا لَقُواْ ٱلَّذِينَ ءَامَنُواْ قَالُوٓاْ ءَامَنَّا وَإِذَا خَلَوۡاْ إِلَىٰ شَيَٰطِينِهِمۡ قَالُوٓاْ إِنَّا مَعَكُمۡ إِنَّمَا نَحۡنُ مُسۡتَهۡزِءُونَ﴾⟪2:14⟫ الآية (14) - سورة البقرة.\nقال الخليل: كل شيء استقبلته وصادفته فقد لقيته، وأما ألقيته أي طرحته، فأصله جعلته بحيث يلقي أي يصادف، ثم جعل عبارة عن الطرح واللقي المطروح الذي لا يحجزه شيء عن لقاء المارة به.\nولقي من اللقوة كناية بذلك عنها، ثم كثر حتى صار معروفا بالداء.\nو\" خلا الإناء \" صار خاليا، و \" خلا فلان بفلان \" صار معه في خلاء والخلي: من خلاه الهم، نحو المطلق في قوله: يطلقه \".\nطورا وطورا\n⟦1:103⟧\nيراجع، والشياطين: جمع الشيطان، فقيل هو \" غعلان \" من شاط إذا احترق غضبان وذلك لما قال تعالى: ﴿وَخَلَقَ ٱلۡجَآنَّ مِن مَّارِجٖ مِّن نَّارٖ﴾⟪55:15⟫، وذلك لما خص به من فضل القوة الغضبية، وقيل هو فيعال من شطن، أي تباعد، ومنه بين شطوان، وقيل للحبل الطويل شطن، والشيطان كل عارم من الجن والإنس والحيوانات، وعلى ذلك قال الشاعر شياطين تنزوا بعضهم على بعض [وقال: \" إن شطان الذئاب العسل \"، وقال آخر: \" ما ليلة الفقير إلا شيطان \"، وسمي الحية شيطانا لذلك، وقيل هو فعلان من قولهم: وقد شط على أرماحنا البطل، ومعنى الآية، أنهم يراؤن للمؤمنين، فإذا عادوا إلى مردتهم ادعوا أنهم معهم وعلى دينهم، وأنهم يستهزؤن بالمؤمنين."}, {"a": [15], "v": 1, "p": 103, "ev": 1, "ep": 105, "sid": 104, "t": "وقوله تعالى: ﴿ٱللَّهُ يَسۡتَهۡزِئُ بِهِمۡ وَيَمُدُّهُمۡ فِي طُغۡيَٰنِهِمۡ يَعۡمَهُونَ﴾⟪2:15⟫ الآية: (15) - سورة البقرة -.\nالهزء: إظهار جد يراد به مزح أو ما هو في الظاهر كالمزح يقال: هزأت واستهزأت، نحو أجبت، واستجبت، والصحيح أن الاستهزاء إرتياد الهزؤ وإن كان قد يعبر به عنه، وكذا الاستجابة في الأصل معناها مخالف للإجابة وإن كان قد يجري مجراها، والهزؤ إذا أريد به المزح لا يصح منه تعالى، كما لا يصح منه اللعب واللهو وإطلاقه عليه، إما لأنه يراد به المجازاة، فسماه به إما لمقابلة اللفظ باللفظ إما مع مقابلة اللفظ مراعاة مطابقة ما لكونه مماثلا له في القدر، فسماه لذلك باسمه نحو قوله تعالى: ﴿وَجَزَٰٓؤُاْ سَيِّئَةٖ سَيِّئَةٞ مِّثۡلُهَاۖ﴾⟪42:40⟫ وقوله تعالى: ﴿فَمَنِ ٱعۡتَدَىٰ عَلَيۡكُمۡ فَٱعۡتَدُواْ عَلَيۡهِ بِمِثۡلِ مَا ٱعۡتَدَىٰ عَلَيۡكُمۡۚ﴾⟪2:194⟫ ولأنه تعالى لما أمهلهم لتطول المدة التي يمكنهم أن يتوبوا فيها فلم يحصل ذلك منهم سمي إمهاله هزؤا، ولأنه لما استدرجهم من حيث لا يعلمون صار ذلك كالهزؤ، وإما لأن الهزؤ لما لم يخل\n⟦1:104⟧\nمن العيب أطلق على العيب لفظ الهزؤ ونحو قوله: ﴿إِذَا سَمِعۡتُمۡ ءَايَٰتِ ٱللَّهِ يُكۡفَرُ بِهَا﴾⟪4:140⟫ أي تعاب، فالآيات لا يستهزؤ بهما في الحقيقة، أو لما تقدم في المخادعة وهو أنهم لما قدروا أنهم يهزؤن وقد عرف منهم الهزؤ كأنه يهزؤ بهم كما قيل: من خدعك وقد عرفت خديعته فقد خدعته \" أو لما روي في الخبر \" إن المستهزئين بالناس في الدنيا يفتح لهم وهم في النار باب إلى الجنة فيرسعون نحوه، فإذا صاروا إليه سد عليهم \" وذلك قوله: ﴿فَٱلۡيَوۡمَ ٱلَّذِينَ ءَامَنُواْ مِنَ ٱلۡكُفَّارِ يَضۡحَكُونَ﴾⟪83:34⟫ وعلى هذه الوجوه قوله: ﴿سَخِرَ ٱللَّهُ مِنۡهُمۡ﴾⟪9:79⟫ وأصل المد الجر ومنه المدة، ومدة الجرح، ومد النهر، ومده نهر آخر، وإمداد الجيش، وإمداد الإنسان بالطعام، وقال بعضهم:\nأكثر ما جاء من الإمداد في القرآن فبالخبر، نحو قوله تعالى: ﴿وَأَمۡدَدۡنَٰهُم بِفَٰكِهَةٖ﴾⟪52:22⟫ وقوله ﴿نُمِدُّهُم بِهِۦ مِن مَّالٖ وَبَنِينَ﴾⟪23:55⟫ وقال: وما كان من المد فبالشر نحو قوله تعالى: ﴿وَنَمُدُّ لَهُۥ مِنَ ٱلۡعَذَابِ مَدّٗا﴾⟪19:79⟫ وقال ﴿وَإِخۡوَٰنُهُمۡ يَمُدُّونَهُمۡ فِي ٱلۡغَيِّ﴾⟪7:202⟫ والطغيان في المصادر كالعدوان والكفران، يقال: طغي يطغوا ويطغى، نحو صفا، وحكى: طغيت، والفرق بين عدا، وطغي، وبغي أن العدو أن العدو أن تجاوز المقدار المأمور بالانتهاء إليه والوقوف عنده وعلى ذلك قال: ﴿فَمَنِ ٱعۡتَدَىٰ عَلَيۡكُمۡ فَٱعۡتَدُواْ عَلَيۡهِ﴾⟪2:194⟫ أي من تجاوز معكم المقدار المأمور بالانتهاء إليه، فتجاوزوا معه بقدره، لتكون العدالة محفوظة في المجازاة بالتعدي وأما الطغيان: فتجاوز المكان الذي وقعت فيه، وكأن من أخل بما فطر عليه من المعارف العقلية والمواقف الشرعية فلم يراعها فيما يتحراه ويتعاطاه، فقد طغى، وعلى ذلك قوله: «إنا لما طغى الماء حملناكم في الجارية» أي تجاوز الحد الذي كان عليه من قبل، والبغي: طلب تجاوز\n⟦1:105⟧\nقدر الاستحقاق تجاوزه أم لم يتجاوزه، وأصله الطلب، واستعمل في التكبر، لأن المتكبر طالب منزلة ليس لها بأهل، والعمة في البصيرة كالعمي في البصر، وهو التردد في الضلالة، يقال رجل عامة وعمه، فقوله تعالى: ﴿فِي طُغۡيَٰنِهِمۡ يَعۡمَهُونَ﴾⟪2:15⟫ يصح أن يتعلق بقوله: نمدهم فيكون ذلك عبارة عن خذلانهم عن توفيقه لهم، لا لبخله عليهم، بل لسدهم طريقه على أنفسهم بإعراضهم عنه، ويصح أن يتعلق بقوله: ﴿يَعۡمَهُونَ﴾⟪2:15⟫، ومعناه: يمدهم استصلاحا لهم، وهم مع ذلك يعمهون [في طغيانهم ومثله معنى وتقديرا قوله: ﴿وَنَذَرُهُمۡ فِي طُغۡيَٰنِهِمۡ يَعۡمَهُونَ﴾⟪6:110⟫]\n* * *"}, {"a": [16], "v": 1, "p": 105, "ev": 1, "ep": 106, "sid": 106, "t": "قوله تعالى ﴿أُوْلَٰٓئِكَ ٱلَّذِينَ ٱشۡتَرَوُاْ ٱلضَّلَٰلَةَ بِٱلۡهُدَىٰ فَمَا رَبِحَت تِّجَٰرَتُهُمۡ وَمَا كَانُواْ مُهۡتَدِينَ﴾⟪2:16⟫ الآية (16) - سورة البقرة.\nالمبايعة ضربان: مبايعة سلعة بناض، فيقال لدافع السلعة: بايع، ولدافع الناض مشنري، ومبايعة سلعة بسلعة أو ناض بناض، ويصح أن يقال لكل واحد منهما بائع ومشتري، ولذك بحسب ما يتصور في الثمن والمثمن فأي السلعتين تصورتها بصورة الثمن فأخذه بايع، والآخر مشتري، ولهاذ الشأن صار البائع والمشتري من الأسماء المشتركة المعدودة في باب الأضداد والمشاراة وإن كانت موضوعة لمعاملة في أعيان على وجه مخصوص فقد يتحرز بها في كثير من المعارضات فيقال لمن أفرح عن شيء في يده مخصلا به غيره قد باعه به، وقد يقال لمن رغب عن شيء طمعا في غيره.\nوقوله تعالى ﴿إِنَّ ٱللَّهَ ٱشۡتَرَىٰ مِنَ ٱلۡمُؤۡمِنِينَ أَنفُسَهُمۡ وَأَمۡوَٰلَهُم﴾⟪9:111⟫ الآية - ومعناه : أراد منهم أن يبذلوا مهجهم وأموالهم في سبيله، فيجعل لهم بذلك الجنة، فسمي ذلك شري، وقد تقدم أن الهدي يقال على أربعة أوجة: الأول: لما جعله الله للإنسان بالفطرة، والثاني: لما جعله له بالوحي، والثالث: لما يكتسبه الإنسان بالفكر والنظر والعمل والرابع: زيادة الهدي في الدنيا، وطريق الجنة في الآخرة، فكذلك.\nالضلال على أربعة أوجه مقابل للهداية، فالأول: إضاعة الإنسان ما جعله الله له بالفطرة من العقل الغزيزي، وذلك بأن لا يزكيه كما قال تعالى: ﴿وَقَدۡ خَابَ مَن دَسَّىٰهَا﴾⟪91:10⟫.\nوالثاني: إضاعته لما أنزل الله تعالى على ألسنة الأنبياء.\nوالثالث: لما يكتسبه الإنسان بالفكر والنظر والعمل.\nوالرابع: أن يترك ما يستحق به زيادة الهدي في الدنيا والثواب في الآخرة، وقد علم من هذا أن من الضلال ما هو\n⟦1:106⟧\nكفر، ومنه ما ذنب صغير، وكذلك الهدي منه ما هو الإسلام، ومنه ما هو الإسلام، ومنه ما هو رفيق الورع، فكل من رغب عن منزلة من الهدى إلى ضدها من الضلال، فقد اشترى ذلك الضلال بما يقابله من الهدي لكن منه ما يستحق به النار كالشرك، وكالكبائر، ومنه ما هو كتجاف عنه كالصغائر، فإذا ثبت ذلك، فقول من قال: عنى به الذين أخلوا بالهدي الذي جعله الله لهم بالفطرة، وقول مجاهد، إنه عنى به الذين آمنوا ثم كفروا، وقول قتادة: استحبوا الضلالة على الهجى، وقول من قال: اشتروا النار بالجنة لا اختلاف بينهم إلا باختلاف النظرات فقط.\nوكذا قول من قال: من التزم فعلا من الخيرات ثم أخل به فقد اشترى الضلالة بالهدى، ولما استعمل في ذلك المشاراة قال تعالى: ﴿فَمَا رَبِحَت تِّجَٰرَتُهُمۡ﴾⟪2:16⟫ والربح والخسران ينسبان مرة إلى صاحب السلعة، ومرة إلى السلعة، ومرة إلى الصفقة، إذ لا اشتباه فيه، ونحوه قوله تعالى: ﴿إِنَّ ٱلۡخَٰسِرِينَ ٱلَّذِينَ خَسِرُوٓاْ أَنفُسَهُمۡ﴾ ونفي أنهم كانوا مهتدين أي طالبين للهدى تنبيها أنهم لو طلبوع لوجدوه."}, {"a": [17, 18], "v": 1, "p": 106, "ev": 1, "ep": 107, "sid": 107, "t": "قوله - عز وجل - ﴿مَثَلُهُمۡ كَمَثَلِ ٱلَّذِي ٱسۡتَوۡقَدَ نَارٗا فَلَمَّآ أَضَآءَتۡ مَا حَوۡلَهُۥ ذَهَبَ ٱللَّهُ بِنُورِهِمۡ وَتَرَكَهُمۡ فِي ظُلُمَٰتٖ لَّا يُبۡصِرُونَ﴾⟪2:17⟫ الآية: (17) - سورة البقرة .\nالتمثيل: تصوير الخفي بالظاهر، وأصله من مثل إذا انتصب، والتمثال للشيء المصور، وسمي الوصف مثلا، إذ هو مثال للموصوف يدل عليه كالمثال في دلالته على ما هو مثال له، والمستوقد: طالب الوقود وأخذه، وقد يقال للموقد للمجيب مستجب، والنار حرارة مخصوصة والنور والضياء وأحدهما مشتق من الآخر من حيث إنه قل ما ينفك أحدهما عن الآخر، ولهاذ قال: ﴿نَقۡتَبِسۡ مِن نُّورِكُمۡ﴾⟪57:13⟫ فاستعمل فيه الاقتباس الذي هو للنار، ويقال: أضاءت الشيء فضاء وأضاء والأظهر في الآية أن يكون متعديا لإدخال حرف التأنيث فيه والآية مثل ضربه الله لمن آتاه ضربا من الهداية والمعارف النفسية أو البدنية أو الخارجة، فأضاعه ولم يتوصل به إلى النعيم الأبد فإذا قول من قال ذلك هو فيمن آثر الضلالة على الهدى المجعول له بالفطرة، وقول من قال: هو في الذين آمنوا ثم كفروا، وقول من قال: هو فيمن أظهر الإيمان نفاقا منه وحقنا لدمه، كل ذلك داخل في عمومه، وكذا قول من قال إنه يعني من لم تصح له أحوال الإرادة، فارتقى منها بالدعوى إلى أحوال المحبة، فأذهب الله عنه ما جعل له من النور عبد الإرادة، فبقي متحيرا في حال الدعوى، وقد نبه تعالى بتشبيههم بمستوقد نار أضيع نورها على حيرتهم أو نكسهم فيما أضاءه من الهدى، وقوله: ﴿ذَهَبَ ٱللَّهُ بِنُورِهِمۡ﴾⟪2:17⟫ الأظهر أن يكون ذلك راجعا إلى المشبه الذي هو في قوله: \" مثلهم \" دون المشبه به الذي هو\n⟦1:107⟧\nقوله استوقد نارا، واختصر، ولو بسط الكلام، لقيل: \" فلما اضاءت ما حوله ذهب الله بنارهم ذهابه بنورهم وقد قيل: إن ذلك يرجع إلى المشبه به، وأن الذي قد يستعمل في الجميع كاستعماله في الواحد - استدلالا بقول الشاعر:\nفإت الذي خانت بفلج دماءهم هم القوم، هم فقال: استوقد ردا إلى لفظ الذي ثم قال بنورهم ردا إلى معنى الجمع، وإنما قال على هذا \" بنورهم \" ولم يقل \" بنارهم \"، لأن المراد من النار ههنا النور الذي يضئ لهم الطريق فتركه إياهم في ظلمات إنما هو لتركهم إياه في قبول التوفيق منه، فلما تركوه تركهم كما قال تعالى: ﴿نَسُواْ ٱللَّهَ فَنَسِيَهُمۡۚ﴾⟪9:67⟫، وإنما قال: في \" ظلمات \" لأنه عنى ظلمة ضلال لهم، وظلمة همومهم في الدنيا، وظلمة يوم القيامة التي تنزه عنها الموصوفون بقوله تعالى ﴿يَوۡمَ تَرَى ٱلۡمُؤۡمِنِينَ وَٱلۡمُؤۡمِنَٰتِ يَسۡعَىٰ نُورُهُم بَيۡنَ أَيۡدِيهِمۡ وَبِأَيۡمَٰنِهِمۖ﴾⟪57:12⟫، وقوله - عز وجل - ﴿صُمُّۢ بُكۡمٌ عُمۡيٞ فَهُمۡ لَا يَرۡجِعُونَ﴾⟪2:18⟫ والصم صلابة من اكتناز الأجزاء، ومنه قيل: حجر أصم، وصخرة صماء، أو قناة صماء، وقيل لرأس القارورة \" الصمام \" والبكم: اعتقال اللسان وأصله فيمن يولد أخرس والعمي يقال في عدم البصيرة والبصر، جميعا، فمن ترك الإصغاء إلى الحكمة وأعرض عن طريق الآخرة واشتغل عن تعرف حالها ولم ينعم تدبرها صح أن يستعمل هذه الألفاظ فيه، فيقال: هو أصم عن سماعه، وأبكم عن تعرفه، وأعمى عن إدراكه، ومالآية مبنية على الآية الأولى، ومفسرة بحسب تفسيرها، وقوله ﴿لَا يَرۡجِعُونَ﴾⟪2:18⟫ أي لا يعودون إلى طريقة الرشد، وقيل معناه: \" لا يرجعون جوابا \" أي لا يردونه.\n* * *"}, {"a": [19, 20], "v": 1, "p": 107, "ev": 1, "ep": 109, "sid": 108, "t": "قوله تعالى ﴿أَوۡ كَصَيِّبٖ مِّنَ ٱلسَّمَآءِ فِيهِ ظُلُمَٰتٞ وَرَعۡدٞ وَبَرۡقٞ يَجۡعَلُونَ أَصَٰبِعَهُمۡ فِيٓ ءَاذَانِهِم مِّنَ ٱلصَّوَٰعِقِ حَذَرَ ٱلۡمَوۡتِۚ وَٱللَّهُ مُحِيطُۢ بِٱلۡكَٰفِرِينَ ۝ يَكَادُ ٱلۡبَرۡقُ يَخۡطَفُ أَبۡصَٰرَهُمۡۖ كُلَّمَآ أَضَآءَ لَهُم مَّشَوۡاْ فِيهِ وَإِذَآ أَظۡلَمَ عَلَيۡهِمۡ قَامُواْۚ وَلَوۡ شَآءَ ٱللَّهُ لَذَهَبَ بِسَمۡعِهِمۡ وَأَبۡصَٰرِهِمۡۚ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ﴾⟪2:19-20⟫\nالآيتان (19، 20) - سورة البقرة.\nالصيب: فيعل من \" صاب \" يصوب، وذلك يقال للسحاب والمطر وإن كان الصيب في السحاب أكثر، والصوب يقال في المطر، وكأن المطر تسمي صوبا لمجيئه على الصواب إما اعتبارا بالوقت المحتاج إليه فيه، وإما بالقدر المعتدل على حسب قوله تعالى: ﴿وَٱلَّذِي نَزَّلَ مِنَ ٱلسَّمَآءِ مَآءَۢ بِقَدَرٖ﴾⟪43:11⟫ وعلى طريقه نظر من وصف المطلر بقوله ..\n⟦1:108⟧\nفسقى ديارك غير مفسدها ...\nصوب الربيع وديمة تهمى\nوأصاب السهم إذا توجه نحو الرمية على الصواب، وقد شبه العقل والقرآن بل العلوم كلها بالمطر والماء من حيث أنه سبب الحياة الأبدية، كما أن الماء سبب الحياة الدنيوية والسماء في هذا الموضوع يجوز أن يكون السحاب وأن يكون المطر، من فيه للتبغيض، وقوله \" فيه ظلمات \" يقتضي معنى اللصطحاب، فلا فرق بين أن يقال: صيب فيه ظلمة ورعد - وأما الكلام في مائية الرعد والبرق فليس يليق بهذا الموضع، والصاعقة يستعمل في كل هائل عظيم من مرئي ومسموع، وإنما قال: \" أو كصيب \"، لأنه من حيث أنه يدل على أحد الشيئين، ويستعمل في الإباحة والتخيير، وفيه تنبيه على أنه إن شبه بأحدهما فصواب، وإن شبه بهما فصواب، وهذا المعنى في لفظه أو دون الواو، فإن قيل كيف وجه العطف في ذلك وقد قال في الأول ﴿مَثَلُهُمۡ كَمَثَلِ ٱلَّذِي ٱسۡتَوۡقَدَ نَارٗا﴾⟪2:17⟫ ولا يليق أن يقال بعده.\n\" أو كصيب \"؟ قيل: قد أجيب عن ذلك بانه أريد أو كاهل صيب من السماء، وقيل: إن ذلك عطف على المعنى وذاك أن التشبيه تارة يؤتي به مطابقا للمشبه في اللفظ، وتارة يؤتي به على ما يقتضيه المعنى دون اللفظ وعلى ذلك قوله تعالى: ﴿مَثَلُ مَا يُنفِقُونَ فِي هَٰذِهِ ٱلۡحَيَوٰةِ ٱلدُّنۡيَا كَمَثَلِ رِيحٖ فِيهَا صِرٌّ أَصَابَتۡ حَرۡثَ قَوۡمٖ ظَلَمُوٓاْ أَنفُسَهُمۡ﴾⟪3:117⟫ ومعناه كحرث قوم ظلموا أنفسهم أصابته ريح، فروعي فيه المعنى دون اللفظ، وعلى ذلك قول الشاعر:\nفلابنة حطان بن عوف منازل ...\nكما رقش العنوان في الرق كاتب\nوتقديره: كعنوان رقشه الكاتب، وهذا النوع من التشبيه يقال له: التشبيه الملقف، والآية تأولت على وجهين: أحدهما أنه شبه حال المتحرين الذين اشتروا الضلالة بالهدى بمن حصل في ليلة مطيرة ومظلمة راعدة بارقة يخاف من أهوالها وصاعقتها ويسد أذنه خوفا من أن يصعق ويكون هذا في شغل الكلام بالمشبه به ووصفه بما يعظم من غير أن يكون في تفاصيل صفة المشبه به ما يرجع إلى المشبه طريقة العرب على ذلك قول لبيد.\nأفتلك أم وحشية مسبوعة ...\nخذلت وهادية الصوار قوامها\n⟦1:109⟧\nفشبه الناقة بالوحشية ثم ذكر أنها مسبوعة مخذولة، ولا اختصاص للناقة بهذا الوصف.\nوالثاني: أنه شبه ما أتى الله الإنسان من المعاون التي هي سبب الحياة الأبدية بالصيب الذي فيه خياة كل ذي حياة، وما فيه من المشاق المبهمة والعوارض المشكلة بظلمات، وجمع الظلمات تنبيها على كثرة العوارض، وشبه ما فيه من الوعيد بالرعد، وما فيه من الآيات الباهرة بالبرق، ثم ذكر كل واحد من هذه الأشياء فقال: إذا سمعوا وعيدا تصاموا عنه كحال من تهوله الرعد فيخاف من صواعقه، فيسد أذنه عنها مع أنه لا خلاص لهم منها وهذا معنى قوله: \" الله محيط بالكافرين \"، ثم ذكر أنه إذا رأوا لامعا لهم إما راشد تدركه بصائرهم وإما رفدا ينفعهم اهتزوا له، فمضوا بنوره وذلك قوله \" كلما أضاء لهم مشوا فيه \"، ثم بين أنه إن اعترض لهم شبهة أو عن لهم مصيبة تحيروا، فوقفوا، وذلك معنى قوله ﴿وَإِذَآ أَظۡلَمَ عَلَيۡهِمۡ قَامُواْۚ﴾⟪2:20⟫ وقوله ﴿وَلَوۡ شَآءَ ٱللَّهُ لَذَهَبَ بِسَمۡعِهِمۡ وَأَبۡصَٰرِهِمۡۚ﴾⟪2:20⟫ تنبيها على أنهم يصرفون أسماعهم وأبصارهم عما فيه نجاتهم وتأمل ما فيه صلاحهم وإنما جعل الله لهم السمع والأبصار لينفعهم ولو شاء الله لجعلهم بالحالة التي أنفسهم عليها يسدهما وتعطيلهما، وذلك تنبيه على أنه إنما أعطاهم هذه الآلات لينتفعوا بها."}];
